{
  "name": "SIPEBI-PTP (Sistem Penilaian Aset Belajar)",
  "description": "Aplikasi evaluasi aset pembelajaran otomatis untuk Pengembang Teknologi Pembelajaran (PTP) yang mendeteksi kesalahan penulisan, kelengkapan logo Kemenkes, dan panduan penggunaan menggunakan AI.",
  "requestFramePermissions": []
}

export enum EvaluationStatus {
  PASS = 'PASS',
  FAIL = 'FAIL',
  WARNING = 'WARNING'
}

export interface EvaluationDetail {
  criterion: string;
  status: EvaluationStatus;
  finding: string;
  recommendation: string;
}

export interface EvaluationReport {
  assetName: string;
  overallScore: number;
  logoDetected: boolean;
  userGuidePresent: boolean;
  typosFound: string[];
  details: EvaluationDetail[];
  summary: string;
}

export interface AppState {
  file: File | null;
  isAnalyzing: boolean;
  report: EvaluationReport | null;
  error: string | null;
  progress: number;
}

import { GoogleGenAI, Type } from "@google/genai";
import { EvaluationReport } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export async function analyzeLearningAsset(
  imageParts: { inlineData: { data: string; mimeType: string } }[],
  fileName: string
): Promise<EvaluationReport> {
  const model = "gemini-3-flash-preview";

  const systemInstruction = `
    Anda adalah seorang Pengembang Teknologi Pembelajaran (PTP) Ahli. 
    Tugas Anda adalah mengevaluasi dokumen aset pembelajaran (PDF) berdasarkan kriteria berikut:
    1. Logo Kemenkes: Harus ada di halaman sampul atau header.
    2. Panduan Penggunaan Aset: Harus tersedia instruksi cara menggunakan aset tersebut.
    3. Kesalahan Penulisan (Typo): Cari kesalahan ejaan dalam Bahasa Indonesia (sesuai PUEBI/KBBI).
    4. Kualitas Layout: Apakah layout rapi dan profesional.

    Analisislah gambar-gambar halaman PDF yang diberikan dan berikan laporan dalam format JSON.
  `;

  const responseSchema = {
    type: Type.OBJECT,
    properties: {
      assetName: { type: Type.STRING },
      overallScore: { type: Type.NUMBER, description: "Skor dari 0-100" },
      logoDetected: { type: Type.BOOLEAN },
      userGuidePresent: { type: Type.BOOLEAN },
      typosFound: { 
        type: Type.ARRAY, 
        items: { type: Type.STRING } 
      },
      details: {
        type: Type.ARRAY,
        items: {
          type: Type.OBJECT,
          properties: {
            criterion: { type: Type.STRING },
            status: { type: Type.STRING, description: "PASS, FAIL, or WARNING" },
            finding: { type: Type.STRING },
            recommendation: { type: Type.STRING }
          },
          required: ["criterion", "status", "finding", "recommendation"]
        }
      },
      summary: { type: Type.STRING }
    },
    required: ["assetName", "overallScore", "logoDetected", "userGuidePresent", "typosFound", "details", "summary"]
  };

  const prompt = `Analisis aset pembelajaran berjudul "${fileName}" dari gambar-gambar terlampir.`;

  try {
    const response = await ai.models.generateContent({
      model: model,
      contents: [
        {
          parts: [
            ...imageParts,
            { text: prompt }
          ]
        }
      ],
      config: {
        systemInstruction: systemInstruction,
        responseMimeType: "application/json",
        responseSchema: responseSchema,
      },
    });

    const result = JSON.parse(response.text);
    return result as EvaluationReport;
  } catch (error) {
    console.error("Gemini Analysis Error:", error);
    throw new Error("Gagal menganalisis dokumen. Pastikan dokumen terbaca dengan jelas.");
  }
}

import React from 'react';
