      case EvaluationStatus.PASS: return 'bg-emerald-100 text-emerald-700 border-emerald-200';
      case EvaluationStatus.FAIL: return 'bg-rose-100 text-rose-700 border-rose-200';
      case EvaluationStatus.WARNING: return 'bg-amber-100 text-amber-700 border-amber-200';
      default: return 'bg-slate-100 text-slate-700 border-slate-200';
    }
  };

  const getStatusIcon = (status: EvaluationStatus) => {
    switch (status) {
      case EvaluationStatus.PASS:
        return (
          <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M5 13l4 4L19 7" />
