import React, { useState, useRef, useCallback } from 'react';
import Header from './components/Header';
import ReportView from './components/ReportView';
import { AppState, EvaluationReport } from './types';
import { analyzeLearningAsset } from './services/geminiService';

// PDF.js worker setup
// @ts-ignore
const pdfjsLib = window['pdfjs-dist/build/pdf'];
pdfjsLib.GlobalWorkerOptions.workerSrc = 'https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.worker.min.js';

const App: React.FC = () => {
  const [state, setState] = useState<AppState>({
    file: null,
    isAnalyzing: false,
    report: null,
    error: null,
    progress: 0,
  });

  const fileInputRef = useRef<HTMLInputElement>(null);

  const extractImagesFromPdf = async (file: File): Promise<{ inlineData: { data: string; mimeType: string } }[]> => {
    const arrayBuffer = await file.arrayBuffer();
    const pdf = await pdfjsLib.getDocument({ data: arrayBuffer }).promise;
    const images: { inlineData: { data: string; mimeType: string } }[] = [];

    // We analyze up to first 5 pages to save tokens and time while covering cover, TOC, and initial guide
    const pagesToAnalyze = Math.min(pdf.numPages, 5);

    for (let i = 1; i <= pagesToAnalyze; i++) {
      setState(prev => ({ ...prev, progress: Math.round((i / pagesToAnalyze) * 50) }));
      const page = await pdf.getPage(i);
      const viewport = page.getViewport({ scale: 1.5 });
      const canvas = document.createElement('canvas');
      const context = canvas.getContext('2d');
      canvas.height = viewport.height;
      canvas.width = viewport.width;

      if (context) {
        await page.render({ canvasContext: context, viewport }).promise;
        const base64Image = canvas.toDataURL('image/jpeg', 0.8).split(',')[1];
        images.push({
          inlineData: {
            data: base64Image,
            mimeType: 'image/jpeg'
          }
        });
      }
    }
    return images;
  };

  const handleFileUpload = async (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;
    if (file.type !== 'application/pdf') {
      setState(prev => ({ ...prev, error: 'Hanya file PDF yang didukung.' }));
      return;
    }

    setState({
      file,
      isAnalyzing: true,
      report: null,
      error: null,
      progress: 0,
    });

    try {
      // 1. Convert PDF pages to images
      const images = await extractImagesFromPdf(file);

      setState(prev => ({ ...prev, progress: 60 }));

      // 2. Call Gemini for Analysis
      const report = await analyzeLearningAsset(images, file.name);

      setState(prev => ({
        ...prev,
        isAnalyzing: false,
        report,
        progress: 100
      }));
    } catch (err: any) {
      setState(prev => ({
        ...prev,
        isAnalyzing: false,
        error: err.message || 'Terjadi kesalahan saat menganalisis.'
      }));
    }
  };

  const reset = () => {
    setState({
      file: null,
      isAnalyzing: false,
      report: null,
      error: null,
      progress: 0,
    });
    if (fileInputRef.current) fileInputRef.current.value = '';
  };

  return (
    <div className="min-h-screen flex flex-col">
      <Header />

      <main className="flex-grow max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-10 w-full">
        {/* Welcome Section */}
        {!state.report && !state.isAnalyzing && (
          <div className="max-w-3xl mx-auto text-center space-y-8 py-12">
            <div className="space-y-4">
              <h2 className="text-4xl font-extrabold text-slate-900 tracking-tight sm:text-5xl">
                Evaluasi Aset Belajar <span className="text-emerald-600">Lebih Cerdas.</span>
              </h2>
              <p className="text-xl text-slate-500 leading-relaxed">
                Platform otomatis untuk Pengembang Teknologi Pembelajaran (PTP) dalam memastikan kualitas dokumen modul, e-book, dan panduan belajar sesuai standar Kemenkes.
              </p>
            </div>

            <div 
              onClick={() => fileInputRef.current?.click()}
              className="relative group cursor-pointer"
            >
              <div className="absolute -inset-1 bg-gradient-to-r from-emerald-600 to-teal-500 rounded-2xl blur opacity-25 group-hover:opacity-50 transition duration-1000 group-hover:duration-200"></div>
              <div className="relative bg-white border-2 border-dashed border-slate-300 rounded-2xl p-12 transition-all hover:border-emerald-400 hover:shadow-xl">
                <input 
                  type="file" 
                  ref={fileInputRef}
                  onChange={handleFileUpload}
                  accept=".pdf"
                  className="hidden" 
                />
                <div className="flex flex-col items-center">
                  <div className="w-16 h-16 bg-emerald-50 rounded-full flex items-center justify-center mb-4 group-hover:scale-110 transition-transform">
                    <svg xmlns="http://www.w3.org/2000/svg" className="h-8 w-8 text-emerald-600" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M7 16a4 4 0 01-.88-7.903A5 5 0 1115.9 6L16 6a5 5 0 011 9.9M15 13l-3-3m0 0l-3 3m3-3v12" />
                    </svg>
                  </div>
                  <span className="text-lg font-bold text-slate-900 mb-1">Pilih File PDF Aset Belajar</span>
                  <p className="text-slate-400 text-sm">Seret file ke sini atau klik untuk mencari (Maks. 10MB)</p>
                </div>
              </div>
            </div>

            <div className="grid grid-cols-1 sm:grid-cols-3 gap-6 text-left pt-8">
              <div className="flex gap-4 items-start">
                <div className="bg-emerald-100 p-2 rounded-lg text-emerald-600">
                  <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M9 12l2 2 4-4m5.618-4.016A11.955 11.955 0 0112 2.944a11.955 11.955 0 01-8.618 3.04A12.02 12.02 0 003 9c0 5.591 3.824 10.29 9 11.622 5.176-1.332 9-6.03 9-11.622 0-1.042-.133-2.052-.382-3.016z" /></svg>
                </div>
                <div>
                  <h4 className="font-bold text-slate-800 text-sm">Deteksi Logo</h4>
                  <p className="text-xs text-slate-500">Mendeteksi keberadaan logo resmi Kemenkes.</p>
                </div>
              </div>
              <div className="flex gap-4 items-start">
                <div className="bg-emerald-100 p-2 rounded-lg text-emerald-600">
                  <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M3 5h12M9 3v2m1.048 9.583L9 14.066l-1.048-1.483m2.096 0A8.003 8.003 0 0112 11h2a2 2 0 002-2V7a2 2 0 00-2-2H9V3m-4 5h4" /></svg>
                </div>
                <div>
                  <h4 className="font-bold text-slate-800 text-sm">Analisis PUEBI</h4>
                  <p className="text-xs text-slate-500">Mendeteksi kesalahan ketik & tata bahasa.</p>
                </div>
              </div>
              <div className="flex gap-4 items-start">
                <div className="bg-emerald-100 p-2 rounded-lg text-emerald-600">
                  <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 6.253v13m0-13C10.832 5.477 9.246 5 7.5 5S4.168 5.477 3 6.253v13C4.168 18.477 5.754 18 7.5 18s3.332.477 4.5 1.253m0-13C13.168 5.477 14.754 5 16.5 5c1.747 0 3.332.477 4.5 1.253v13C19.832 18.477 18.247 18 16.5 18c-1.746 0-3.332.477-4.5 1.253" /></svg>
                </div>
                <div>
                  <h4 className="font-bold text-slate-800 text-sm">Struktur Panduan</h4>
                  <p className="text-xs text-slate-500">Memastikan instruksi belajar tersedia.</p>
                </div>
              </div>
            </div>
          </div>
        )}

        {/* Loading State */}
        {state.isAnalyzing && (
          <div className="max-w-2xl mx-auto py-20 text-center space-y-8">
            <div className="relative inline-block">
              <div className="w-24 h-24 border-4 border-slate-100 border-t-emerald-600 rounded-full animate-spin mx-auto"></div>
              <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2">
                <span className="text-xs font-bold text-emerald-600">{state.progress}%</span>
              </div>
            </div>
            <div className="space-y-3">
              <h3 className="text-2xl font-bold text-slate-900 animate-pulse">Sedang Menganalisis Dokumen...</h3>
              <p className="text-slate-500 italic">"AI sedang meninjau tata bahasa, mencari logo, dan memverifikasi kelengkapan struktur aset..."</p>
            </div>

            <div className="w-full bg-slate-100 rounded-full h-3 max-w-md mx-auto overflow-hidden">
               <div 
                className="bg-emerald-600 h-full transition-all duration-500 rounded-full shadow-[0_0_10px_rgba(5,150,105,0.5)]" 
                style={{ width: `${state.progress}%` }}
              ></div>
            </div>
          </div>
        )}

        {/* Error State */}
        {state.error && (
          <div className="max-w-xl mx-auto bg-rose-50 border border-rose-100 p-6 rounded-2xl flex flex-col items-center gap-4 text-center">
            <div className="w-12 h-12 bg-rose-100 text-rose-600 rounded-full flex items-center justify-center">
              <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-3L13.732 4c-.77-1.333-2.694-1.333-3.464 0L3.34 16c-.77 1.333.192 3 1.732 3z" />
              </svg>
            </div>
            <div className="space-y-1">
              <h4 className="text-lg font-bold text-rose-900">Analisis Gagal</h4>
              <p className="text-rose-700 text-sm">{state.error}</p>
            </div>
