            >
              Coba Lagi
            </button>
          </div>
        )}

        {/* Report Result */}
        {state.report && (
          <ReportView report={state.report} onReset={reset} />
        )}
      </main>

      <footer className="bg-white border-t border-slate-200 py-8">
        <div className="max-w-7xl mx-auto px-4 text-center space-y-2">
          <p className="text-slate-500 text-sm font-medium">© 2024 SIPEBI-PTP. Dikembangkan untuk Pengembang Teknologi Pembelajaran Indonesia.</p>
          <p className="text-slate-400 text-xs">Aplikasi ini menggunakan teknologi Gemini 3 Flash Preview untuk analisis dokumen otomatis.</p>
        </div>
      </footer>
    </div>
  );
};

export default App;

