}

import { GoogleGenAI, Type } from "@google/genai";
import { EvaluationReport, ChatMessage } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export async function analyzeLearningAsset(
  imageParts: { inlineData: { data: string; mimeType: string } }[],
  fileName: string
): Promise<EvaluationReport> {
  const model = "gemini-3-flash-preview";

  const systemInstruction = `
    Anda adalah seorang Pengembang Teknologi Pembelajaran (PTP) Ahli. 
    Tugas Anda adalah mengevaluasi dokumen aset pembelajaran (PDF) berdasarkan kriteria berikut:
    1. Logo Kemenkes: Harus ada di halaman sampul atau header.
    2. Panduan Penggunaan Aset: Harus tersedia instruksi cara menggunakan aset tersebut.
    3. Kesalahan Penulisan (Typo): Cari kesalahan ejaan dalam Bahasa Indonesia (sesuai PUEBI/KBBI).
    4. Kualitas Layout: Apakah layout rapi dan profesional.

    Analisislah gambar-gambar halaman PDF yang diberikan dan berikan laporan dalam format JSON.
  `;

  const responseSchema = {
    type: Type.OBJECT,
    properties: {
      assetName: { type: Type.STRING },
      overallScore: { type: Type.NUMBER },
      logoDetected: { type: Type.BOOLEAN },
      userGuidePresent: { type: Type.BOOLEAN },
      typosFound: { type: Type.ARRAY, items: { type: Type.STRING } },
      details: {
        type: Type.ARRAY,
        items: {
          type: Type.OBJECT,
          properties: {
            criterion: { type: Type.STRING },
            status: { type: Type.STRING },
            finding: { type: Type.STRING },
            recommendation: { type: Type.STRING }
          },
          required: ["criterion", "status", "finding", "recommendation"]
        }
      },
      summary: { type: Type.STRING }
    },
    required: ["assetName", "overallScore", "logoDetected", "userGuidePresent", "typosFound", "details", "summary"]
  };

  const response = await ai.models.generateContent({
    model: model,
    contents: [{ parts: [...imageParts, { text: `Analisis aset pembelajaran: ${fileName}` }] }],
    config: {
      systemInstruction: systemInstruction,
      responseMimeType: "application/json",
      responseSchema: responseSchema,
    },
  });

  const result = JSON.parse(response.text);
  return {
    ...result,
    id: crypto.randomUUID(),
    timestamp: Date.now()
  };
}

export async function chatAboutReport(
  report: EvaluationReport,
  userMessage: string,
  history: ChatMessage[]
): Promise<string> {
  const model = "gemini-3-flash-preview";
  const chat = ai.chats.create({
    model: model,
    config: {
      systemInstruction: `Anda adalah asisten PTP Ahli. Anda sedang membantu pengguna mendiskusikan laporan evaluasi aset pembelajaran berikut: ${JSON.stringify(report)}. Berikan saran praktis dan profesional dalam Bahasa Indonesia.`
    }
  });

  const response = await chat.sendMessage({ message: userMessage });
  return response.text || "Maaf, saya tidak bisa merespons saat ini.";
}

