  const [chatHistory, setChatHistory] = useState<ChatMessage[]>([]);
  const [isTyping, setIsTyping] = useState(false);

  const getStatusColor = (status: EvaluationStatus) => {
    switch (status) {
      case EvaluationStatus.PASS: return 'bg-emerald-100 text-emerald-700 border-emerald-200';
      case EvaluationStatus.FAIL: return 'bg-rose-100 text-rose-700 border-rose-200';
      case EvaluationStatus.WARNING: return 'bg-amber-100 text-amber-700 border-amber-200';
