    content += `Skor Keseluruhan: ${report.overallScore}\n`;
    content += `Ringkasan: ${report.summary}\n\n`;
    content += `DETAIL TEMUAN:\n`;
    report.details.forEach(d => {
      content += `- ${d.criterion} [${d.status}]: ${d.finding}\n`;
      content += `  Rekomendasi: ${d.recommendation}\n\n`;
    });
    content += `KESALAHAN PENULISAN:\n`;
    report.typosFound.forEach(t => content += `- ${t}\n`);

    const blob = new Blob([content], { type: 'text/plain' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `SIPEBI_Report_${report.assetName.replace(/\s+/g, '_')}.txt`;
