    2. STANDAR VISUAL:
       - Font Utama: Harus menggunakan jenis font "VAG Rounded".
       - Palette Warna Kemenkes: Memeriksa kesesuaian dengan warna identitas (Tosca #16AF97, Dark Teal #007376, Yellow #D2DB2F, dsb).

    3. STRUKTUR WAJIB (Harus ada):
       - Video Pengantar (Opening)
       - Tim Penyusun (Menampilkan Penanggung Jawab, Penyusun, PTP)
       - Petunjuk Penggunaan Modul (Navigasi & Fitur)
       - Hasil Belajar & Indikator Hasil Belajar
       - Jabaran Materi & Materi Pokok
       - Slide "Sekarang Saya Tahu" (Refleksi)
       - Progress Bar (Indikator visual %)
       - Video Penutup (Closing)

    4. KUALITAS BAHASA:
       - Kesalahan Penulisan (Typo) sesuai PUEBI/KBBI.
       - Penggunaan bahasa formal namun inspiratif.

    Analisislah gambar-gambar halaman PDF yang diberikan dan berikan laporan dalam format JSON.
  `;

  const responseSchema = {
    type: Type.OBJECT,
    properties: {
      assetName: { type: Type.STRING },
      overallScore: { type: Type.NUMBER },
      logoDetected: { type: Type.BOOLEAN, description: "True jika setidaknya ada logo utama Kemenkes/Bapelkes" },
      userGuidePresent: { type: Type.BOOLEAN, description: "True jika ada bagian Petunjuk Penggunaan" },
      typosFound: { type: Type.ARRAY, items: { type: Type.STRING } },
      details: {
        type: Type.ARRAY,
        items: {
          type: Type.OBJECT,
          properties: {
            criterion: { type: Type.STRING },
            status: { type: Type.STRING, description: "PASS, FAIL, or WARNING" },
            finding: { type: Type.STRING },
            recommendation: { type: Type.STRING }
          },
          required: ["criterion", "status", "finding", "recommendation"]
        }
      },
      summary: { type: Type.STRING }
    },
    required: ["assetName", "overallScore", "logoDetected", "userGuidePresent", "typosFound", "details", "summary"]
  };

  const response = await ai.models.generateContent({
    model: model,
    contents: [{ parts: [...imageParts, { text: `Analisis aset pembelajaran: ${fileName}. Berikan perhatian khusus pada keberadaan 4 logo wajib di cover dan elemen struktur seperti 'Sekarang Saya Tahu' dan 'Tim Penyusun'.` }] }],
    config: {
      systemInstruction: systemInstruction,
      responseMimeType: "application/json",
      responseSchema: responseSchema,
    },
  });

  const result = JSON.parse(response.text);
  return {
    ...result,
    id: crypto.randomUUID(),
    timestamp: Date.now()
  };
}

export async function chatAboutReport(
  report: EvaluationReport,
  userMessage: string,
  history: ChatMessage[]
): Promise<string> {
  const model = "gemini-3-flash-preview";
  const chat = ai.chats.create({
    model: model,
    config: {
      systemInstruction: `Anda adalah asisten PTP Ahli. Anda sedang membantu pengguna mendiskusikan laporan evaluasi aset pembelajaran berikut: ${JSON.stringify(report)}. Berikan saran praktis dan profesional dalam Bahasa Indonesia.`
    }
  });

  const response = await chat.sendMessage({ message: userMessage });
  return response.text || "Maaf, saya tidak bisa merespons saat ini.";
}

