    error: null,
    progress: 0,
    chatHistory: [],
    isChatting: false
  });

  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    const saved = localStorage.getItem('sipebi_history');
    if (saved) {
      try {
        setState(prev => ({ ...prev, history: JSON.parse(saved) }));
      } catch (e) { console.error("History parse failed"); }
    }
  }, []);

  const saveToHistory = (report: EvaluationReport) => {
    const updatedHistory = [report, ...state.history].slice(0, 10);
    setState(prev => ({ ...prev, history: updatedHistory }));
    localStorage.setItem('sipebi_history', JSON.stringify(updatedHistory));
  };

  const extractImagesFromPdf = async (file: File) => {
    const arrayBuffer = await file.arrayBuffer();
    const pdf = await pdfjsLib.getDocument({ data: arrayBuffer }).promise;
    const images = [];
    const pagesToAnalyze = Math.min(pdf.numPages, 5);

    for (let i = 1; i <= pagesToAnalyze; i++) {
      setState(prev => ({ ...prev, progress: Math.round((i / pagesToAnalyze) * 40) }));
      const page = await pdf.getPage(i);
      const viewport = page.getViewport({ scale: 1.5 });
      const canvas = document.createElement('canvas');
      const ctx = canvas.getContext('2d');
      canvas.height = viewport.height;
      canvas.width = viewport.width;
      if (ctx) {
        await page.render({ canvasContext: ctx, viewport }).promise;
        images.push({ inlineData: { data: canvas.toDataURL('image/jpeg', 0.8).split(',')[1], mimeType: 'image/jpeg' } });
      }
    }
    return images;
  };

  const handleUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file || file.type !== 'application/pdf') return;

    setState(prev => ({ ...prev, isAnalyzing: true, error: null, progress: 5, view: 'home' }));

    try {
      const images = await extractImagesFromPdf(file);
      setState(prev => ({ ...prev, progress: 60 }));
      const report = await analyzeLearningAsset(images, file.name);
      saveToHistory(report);
      setState(prev => ({ ...prev, isAnalyzing: false, report, view: 'report', progress: 100 }));
    } catch (err: any) {
      setState(prev => ({ ...prev, isAnalyzing: false, error: err.message, progress: 0 }));
