import { GoogleGenAI, Type } from "@google/genai";
import { EvaluationReport, ChatMessage } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export async function analyzeLearningAsset(
  imageParts: { inlineData: { data: string; mimeType: string } }[],
  fileName: string
): Promise<EvaluationReport> {
  const model = "gemini-3-flash-preview";

  const systemInstruction = `
    Anda adalah seorang Pengembang Teknologi Pembelajaran (PTP) Ahli. Evaluasi dokumen PDF aset belajar berdasarkan 13 kategori berikut secara ketat:

    1. KELENGKAPAN LOGO: Cek keberadaan Logo Bapelkes Cikarang, Corporate University, Zona Integritas, dan BerAKHLAK.
    2. STANDAR VISUAL: 
       - Font: Harus VAG Rounded untuk judul.
       - Warna: Harus sesuai Palet Kemenkes (Tosca #16AF97, Dark Teal #007376, Yellow #D2DB2F, Grey #898984, Light Grey #BFBFBF, Dark Grey #63625E, Black #2B2B29, Orange #E4872D, Green #43B178, Olive #C3B82B, Cyan #06B3BC, Cream #F4F7C2, Red #C00000, Pale Cyan #C7EDEC).
    3. VIDEO PENGANTAR & PENUTUP: Cek keberadaan placeholder/halaman video opening & closing.
    4. TIM PENYUSUN: Cek peran (PJ, Penyusun Materi, Pengembang Media/PTP), layout warna, dan font VAG Rounded.
    5. PETUNJUK PENGGUNAAN: Cek navigasi, fitur, layout warna, dan font.
    6. HASIL BELAJAR: Cek pernyataan kurikulum, layout, font, indikasi suara (voice), dan navigasi.
    7. INDIKATOR HASIL BELAJAR: Sama seperti kategori 6.
    8. JABARAN MATERI: Struktur materi sesuai kurikulum, layout, font, dan navigasi.
    9. MATERI POKOK: Uraian sub-materi, link/tautan video, interaktivitas, layout, font, dan navigasi.
    10. REFLEKSI "SEKARANG SAYA TAHU": Ringkasan materi, layout, font, dan navigasi.
    11. PROGRESS BAR (%): Indikator visual kemajuan, layout, font, dan navigasi.
    12. KUALITAS BAHASA (PUEBI): Tata bahasa, ejaan, dan keefektifan kalimat.
    13. KESALAHAN PENULISAN: Deteksi typo, tanda baca salah, kata redundan.

    Berikan skor ASET (0-100). Output harus JSON.
  `;

  const responseSchema = {
    type: Type.OBJECT,
    properties: {
      assetName: { type: Type.STRING },
      overallScore: { type: Type.NUMBER },
      logoDetected: { type: Type.BOOLEAN },
      userGuidePresent: { type: Type.BOOLEAN },
      typosFound: { type: Type.ARRAY, items: { type: Type.STRING } },
      details: {
        type: Type.ARRAY,
        items: {
          type: Type.OBJECT,
          properties: {
            criterion: { type: Type.STRING, description: "Salah satu dari 13 kategori di atas" },
            status: { type: Type.STRING },
            finding: { type: Type.STRING },
            recommendation: { type: Type.STRING }
          },
          required: ["criterion", "status", "finding", "recommendation"]
        }
      },
      summary: { type: Type.STRING }
    },
    required: ["assetName", "overallScore", "logoDetected", "userGuidePresent", "typosFound", "details", "summary"]
  };

  const response = await ai.models.generateContent({
    model: model,
    contents: [{ parts: [...imageParts, { text: `Analisis file: ${fileName} berdasarkan 13 poin standar PTP.` }] }],
    config: {
      systemInstruction: systemInstruction,
      responseMimeType: "application/json",
      responseSchema: responseSchema,
    },
  });

  const result = JSON.parse(response.text);
  return { ...result, id: crypto.randomUUID(), timestamp: Date.now() };
}

export async function chatAboutReport(
  report: EvaluationReport,
  userMessage: string,
  history: ChatMessage[]
): Promise<string> {
  const model = "gemini-3-flash-preview";
  const chat = ai.chats.create({
    model: model,
    config: {
      systemInstruction: `Anda adalah asisten PTP Ahli yang sangat ramah. Gunakan gaya bahasa diskusi teman sejawat. 
      PENTING: Gunakan penomoran (1, 2, 3) atau poin-poin untuk setiap saran agar rapi. 
      Jangan kirim teks blok panjang. Bersikaplah suportif dan humanis.`
    }
  });

  const response = await chat.sendMessage({ message: userMessage });
  return response.text || "Maaf, boleh diulang pertanyaannya?";
}

