import { GoogleGenAI, Type } from "@google/genai";
import { EvaluationReport, ChatMessage } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export async function analyzeLearningAsset(
  input: { imageParts?: { inlineData: { data: string; mimeType: string } }[], textContext?: string },
  fileName: string
): Promise<EvaluationReport> {
  const model = "gemini-3-flash-preview";

  const systemInstruction = `
    Anda adalah seorang Pengembang Teknologi Pembelajaran (PTP) Ahli sekaligus Editor Bahasa Indonesia yang sangat pedantik dan patuh pada KBBI & PUEBI.
    Tugas Anda mengevaluasi aset belajar (PDF/SCORM) berdasarkan standar Kemenkes berikut:

    1. IDENTIFIKASI LOGO (SANGAT SPESIFIK):
       - Logo BerAKHLAK: Tulisan 'BerAKHLAK' warna merah dengan simbol panah merah ke arah kanan atas, di bawahnya terdapat teks nilai-nilai dasar.
       - Logo Zona Integritas: Tulisan 'ZONA INTEGRITAS' warna merah, grafis tangan merah dengan teks 'KORUPSI' yang dicoret/dihalang, dan teks panjang 'WILAYAH BEBAS DARI KORUPSI...' di bawahnya.
       - Logo Kemenkes Corporate University: Simbol bunga/tambah warna Tosca & Hijau Muda di kiri, teks 'Kemenkes' (Tosca) dan 'Corporate University' (Abu-abu).
       - Logo Bapelkes Cikarang: Simbol bunga/tambah warna Tosca & Hijau Muda di kiri, teks 'Kemenkes' (Tosca) dan 'Bapelkes Cikarang' (Abu-abu).

    2. ANALISIS KEBAHASAAN (KBBI & PUEBI):
       - KATA BAKU (KBBI): Deteksi kata tidak baku (misal: 'praktek' -> 'praktik', 'ijazah' -> 'ijazah', 'analisa' -> 'analisis', 'apotik' -> 'apotek').
       - TANDA BACA & SPASI: 
         * Titik/Koma WAJIB menempel pada kata sebelumnya.
         * Setelah titik/koma WAJIB ada satu spasi.
         * Deteksi spasi ganda (double space).
       - REDUNDANSI: Hindari 'adalah merupakan', 'agar supaya', 'sangat ... sekali'.
       - KAPITALISASI: Nama jabatan (Kepala Bapelkes) dan Instansi harus kapital di awal.

    3. STANDAR VISUAL:
       - Font: VAG Rounded untuk judul.
       - Warna: Harus menggunakan palet Kemenkes (Tosca #16AF97, Dark Teal #007376, Yellow #D2DB2F, dll).

    4. STRUKTUR 13 KATEGORI:
       Evaluasi mulai dari Logo, Standar Visual, Video, Tim Penyusun, Petunjuk, Hasil Belajar, Indikator, Jabaran Materi, Materi Pokok, Refleksi, Progress Bar, Bahasa, hingga Typo.

    Berikan skor (0-100). Jika ditemukan typo atau kesalahan tanda baca sekecil apapun, kurangi nilai pada kategori 12 & 13.
    Output harus JSON.
  `;

  const responseSchema = {
    type: Type.OBJECT,
    properties: {
      assetName: { type: Type.STRING },
      overallScore: { type: Type.NUMBER },
      logoDetected: { type: Type.BOOLEAN },
      userGuidePresent: { type: Type.BOOLEAN },
      typosFound: { 
        type: Type.ARRAY, 
        items: { type: Type.STRING },
        description: "Detail kesalahan: kata tidak baku (KBBI), salah tanda baca, spasi ganda, atau redundansi."
      },
      details: {
        type: Type.ARRAY,
        items: {
          type: Type.OBJECT,
          properties: {
            criterion: { type: Type.STRING },
            status: { type: Type.STRING },
            finding: { type: Type.STRING },
            recommendation: { type: Type.STRING }
          },
          required: ["criterion", "status", "finding", "recommendation"]
        }
      },
      summary: { type: Type.STRING }
    },
    required: ["assetName", "overallScore", "logoDetected", "userGuidePresent", "typosFound", "details", "summary"]
  };

  const parts: any[] = [];
  if (input.imageParts) parts.push(...input.imageParts);
  if (input.textContext) parts.push({ text: input.textContext });
  parts.push({ text: `Analisis file: ${fileName}. Fokus pada deteksi logo sesuai referensi visual dan kepatuhan KBBI/PUEBI yang sangat ketat.` });

  const response = await ai.models.generateContent({
    model: model,
    contents: [{ parts }],
    config: {
      systemInstruction: systemInstruction,
      responseMimeType: "application/json",
      responseSchema: responseSchema,
    },
  });

  const result = JSON.parse(response.text);
  return { ...result, id: crypto.randomUUID(), timestamp: Date.now() };
}

export async function chatAboutReport(
  report: EvaluationReport,
  userMessage: string,
  history: ChatMessage[]
): Promise<string> {
  const model = "gemini-3-flash-preview";
  const chat = ai.chats.create({
    model: model,
    config: {
      systemInstruction: `Anda adalah asisten PTP Ahli yang sangat teliti namun tetap humanis. 
      Jika user bertanya tentang kesalahan bahasa, jelaskan aturan KBBI/PUEBI-nya secara edukatif.
      Gunakan penomoran agar jawaban rapi.`
    }
  });

  const response = await chat.sendMessage({ message: userMessage });
  return response.text || "Maaf, koneksi AI terputus.";
}

