              className={`text-sm font-bold transition-colors ${activeView === 'history' ? 'text-emerald-600' : 'text-slate-500 hover:text-emerald-600'}`}
            >
              Riwayat
            </button>
            <button 
              onClick={() => onNavigate('guideline')}
              className={`text-sm font-bold transition-colors ${activeView === 'guideline' ? 'text-emerald-600' : 'text-slate-500 hover:text-emerald-600'}`}
            >
              Panduan Aset
            </button>
          </nav>
        </div>
      </div>
    </header>
  );
};

export default Header;

import React, { useState, useRef, useEffect } from 'react';
import Header from './components/Header';
import ReportView from './components/ReportView';
import GuidelineView from './components/GuidelineView';
import { AppState, EvaluationReport } from './types';
import { analyzeLearningAsset } from './services/geminiService';

// @ts-ignore
const pdfjsLib = window['pdfjs-dist/build/pdf'];
pdfjsLib.GlobalWorkerOptions.workerSrc = 'https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.worker.min.js';
// @ts-ignore
const JSZip = window.JSZip;

const App: React.FC = () => {
  const [state, setState] = useState<AppState>({
    view: 'home',
    file: null,
    isAnalyzing: false,
    report: null,
    history: [],
    error: null,
    progress: 0,
    chatHistory: [],
    isChatting: false
  });

  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    const saved = localStorage.getItem('smartaset_history');
    if (saved) {
      try {
        setState(prev => ({ ...prev, history: JSON.parse(saved) }));
      } catch (e) { console.error("History parse failed"); }
    }
  }, []);

  const saveToHistory = (report: EvaluationReport) => {
    const updatedHistory = [report, ...state.history].slice(0, 10);
    setState(prev => ({ ...prev, history: updatedHistory }));
    localStorage.setItem('smartaset_history', JSON.stringify(updatedHistory));
  };

  const extractImagesFromPdf = async (file: File) => {
    const arrayBuffer = await file.arrayBuffer();
    const pdf = await pdfjsLib.getDocument({ data: arrayBuffer }).promise;
    const images = [];
    const pagesToAnalyze = Math.min(pdf.numPages, 8);

    for (let i = 1; i <= pagesToAnalyze; i++) {
      setState(prev => ({ ...prev, progress: Math.round((i / pagesToAnalyze) * 40) }));
      const page = await pdf.getPage(i);
      const viewport = page.getViewport({ scale: 1.5 });
      const canvas = document.createElement('canvas');
      const ctx = canvas.getContext('2d');
      canvas.height = viewport.height;
      canvas.width = viewport.width;
      if (ctx) {
        await page.render({ canvasContext: ctx, viewport }).promise;
        images.push({ inlineData: { data: canvas.toDataURL('image/jpeg', 0.8).split(',')[1], mimeType: 'image/jpeg' } });
      }
    }
    return images;
  };

  const processScormZip = async (file: File) => {
    const zip = await JSZip.loadAsync(file);
    let textContent = "DATA PAKET SCORM/ZIP:\n\nDaftar File dalam Paket:\n";

    const fileList: string[] = [];
    zip.forEach((relativePath: string) => {
      fileList.push(relativePath);
    });
    textContent += fileList.join("\n") + "\n\nEkstraksi Konten Teks:\n";

    const importantFiles = fileList.filter(f => f.endsWith('.xml') || f.endsWith('.html') || f.endsWith('.htm')).slice(0, 10);

    for (const fileName of importantFiles) {
      const content = await zip.file(fileName)?.async("string");
      if (content) {
        const cleanText = content.replace(/<[^>]*>?/gm, ' ').substring(0, 1000);
        textContent += `--- File: ${fileName} ---\n${cleanText}\n\n`;
      }
    }

    return textContent;
  };

  const handleUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    const isPdf = file.type === 'application/pdf';
    const isZip = file.type === 'application/x-zip-compressed' || file.type === 'application/zip' || file.name.endsWith('.zip');

    if (!isPdf && !isZip) {
      setState(prev => ({ ...prev, error: "Hanya mendukung file PDF atau SCORM (.zip)" }));
      return;
    }

    setState(prev => ({ ...prev, isAnalyzing: true, error: null, progress: 5, view: 'home' }));

    try {
      let analysisResult;
      if (isPdf) {
        const images = await extractImagesFromPdf(file);
        setState(prev => ({ ...prev, progress: 60 }));
        analysisResult = await analyzeLearningAsset({ imageParts: images }, file.name);
      } else {
        setState(prev => ({ ...prev, progress: 30 }));
        const textContext = await processScormZip(file);
        setState(prev => ({ ...prev, progress: 60 }));
        analysisResult = await analyzeLearningAsset({ textContext }, file.name);
      }

      saveToHistory(analysisResult);
      setState(prev => ({ ...prev, isAnalyzing: false, report: analysisResult, view: 'report', progress: 100 }));
    } catch (err: any) {
      console.error(err);
      setState(prev => ({ ...prev, isAnalyzing: false, error: "Gagal menganalisis file. Pastikan format sesuai standar.", progress: 0 }));
    }
  };

  const setView = (v: 'home' | 'history' | 'guideline') => {
    setState(prev => ({ ...prev, view: v }));
  };

  const handleReset = () => {
    setState(prev => ({
      ...prev,
      view: 'home',
      file: null,
      report: null,
      error: null,
      progress: 0,
      chatHistory: []
    }));
    if (fileInputRef.current) fileInputRef.current.value = '';
  };

  return (
    <div className="min-h-screen flex flex-col bg-slate-50">
      <Header onNavigate={setView} activeView={state.view} />

      <main className="flex-grow max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-10 w-full">
        {state.isAnalyzing ? (
          <div className="max-w-xl mx-auto py-20 text-center space-y-8">
            <div className="w-20 h-20 border-4 border-slate-100 border-t-emerald-600 rounded-full animate-spin mx-auto"></div>
            <div className="space-y-4">
              <h3 className="text-xl font-black text-slate-800 tracking-tight">AI Menganalisis Aset Anda...</h3>
              <div className="w-full bg-slate-200 h-1.5 rounded-full overflow-hidden">
                <div className="bg-emerald-600 h-full transition-all duration-300 shadow-[0_0_8px_rgba(16,185,129,0.4)]" style={{ width: `${state.progress}%` }}></div>
              </div>
              <p className="text-sm text-slate-500 italic">"Mengevaluasi konten, struktur, dan kualitas bahasa (KBBI/PUEBI)..."</p>
            </div>
          </div>
        ) : state.view === 'history' ? (
          <div className="max-w-4xl mx-auto space-y-6">
            <h2 className="text-2xl font-black text-slate-900">Riwayat Evaluasi</h2>
            {state.history.length === 0 ? (
              <div className="p-20 text-center bg-white rounded-3xl border border-slate-200">
                <p className="text-slate-400">Belum ada riwayat evaluasi.</p>
              </div>
            ) : (
              <div className="grid gap-4">
                {state.history.map(item => (
                  <div key={item.id} onClick={() => setState(prev => ({ ...prev, report: item, view: 'report' }))} className="bg-white p-5 rounded-2xl border border-slate-200 hover:border-emerald-400 cursor-pointer transition-all flex justify-between items-center group shadow-sm">
                    <div className="flex gap-4 items-center">
                      <div className="w-12 h-12 bg-emerald-50 text-emerald-600 rounded-xl flex items-center justify-center font-black text-lg group-hover:bg-emerald-600 group-hover:text-white transition-colors">{item.overallScore}</div>
                      <div>
                        <h4 className="font-bold text-slate-900">{item.assetName}</h4>
                        <p className="text-xs text-slate-500">{new Date(item.timestamp).toLocaleDateString('id-ID', { day: 'numeric', month: 'long', year: 'numeric' })}</p>
                      </div>
                    </div>
                    <svg className="w-5 h-5 text-slate-300 group-hover:text-emerald-500 transition-colors" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M9 5l7 7-7 7" /></svg>
                  </div>
                ))}
              </div>
            )}
          </div>
        ) : state.view === 'guideline' ? (
          <GuidelineView onNavigate={setView} />
        ) : state.view === 'report' && state.report ? (
          <ReportView report={state.report} onReset={handleReset} />
        ) : (
          <div className="max-w-3xl mx-auto py-12 text-center space-y-12">
            <div className="space-y-4">
              <h2 className="text-4xl md:text-5xl font-black text-slate-900 leading-tight">Pastikan Aset Belajar <span className="text-emerald-600">Sesuai Standar.</span></h2>
              <p className="text-lg text-slate-500">Platform cerdas berbasis AI untuk mengevaluasi dokumen PDF & paket SCORM secara otomatis sesuai kerangka pedoman aset pembelajaran.</p>
            </div>

            <div className="space-y-8">
              <div 
                onClick={() => fileInputRef.current?.click()}
                className="bg-white border-2 border-dashed border-slate-200 rounded-[2rem] p-12 md:p-16 hover:border-emerald-400 hover:bg-emerald-50/30 transition-all cursor-pointer group shadow-xl shadow-slate-200/50"
              >
                <input type="file" ref={fileInputRef} onChange={handleUpload} accept=".pdf,.zip" className="hidden" />
                <div className="flex flex-col items-center gap-6">
                  <div className="w-20 h-20 bg-emerald-100 text-emerald-600 rounded-3xl flex items-center justify-center group-hover:scale-110 transition-transform shadow-inner">
                    <svg className="w-10 h-10" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M9 13h6m-3-3v6m5 5H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z" /></svg>
                  </div>
                  <div>
                    <h3 className="text-xl font-bold text-slate-900 mb-1">Upload PDF atau SCORM (.zip)</h3>
                    <p className="text-slate-400 text-sm">Klik atau seret file di sini untuk mulai evaluasi aset</p>
                  </div>
                </div>
              </div>

              <div className="grid grid-cols-1 md:grid-cols-3 gap-8 text-left px-4">
                <div className="flex gap-4 items-center">
                  <div className="w-10 h-10 bg-white shadow-sm border border-slate-100 rounded-xl flex items-center justify-center text-emerald-600">
                    <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M9 12l2 2 4-4m5.618-4.016A11.955 11.955 0 0112 2.944a11.955 11.955 0 01-8.618 3.04A12.02 12.02 0 003 9c0 5.591 3.824 10.29 9 11.622 5.176-1.332 9-6.03 9-11.622 0-1.042-.133-2.052-.382-3.016z" /></svg>
                  </div>
                  <div>
                    <h4 className="font-bold text-slate-800 text-xs uppercase tracking-wider">Deteksi Logo</h4>
                    <p className="text-[10px] text-slate-500 leading-tight">Logo Kemenkes, Bapelkes, BerAKHLAK, Zona Integritas.</p>
                  </div>
                </div>
                <div className="flex gap-4 items-center">
                  <div className="w-10 h-10 bg-white shadow-sm border border-slate-100 rounded-xl flex items-center justify-center text-emerald-600">
                    <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M3 5h12M9 3v2m1.048 9.583L9 14.066l-1.048-1.483m2.096 0A8.003 8.003 0 0112 11h2a2 2 0 002-2V7a2 2 0 00-2-2H9V3m-4 5h4" /></svg>
                  </div>
                  <div>
                    <h4 className="font-bold text-slate-800 text-xs uppercase tracking-wider">Ejaan PUEBI</h4>
                    <p className="text-[10px] text-slate-500 leading-tight">Analisis kesalahan penulisan & standarisasi Font.</p>
                  </div>
                </div>
                <div className="flex gap-4 items-center">
                  <div className="w-10 h-10 bg-white shadow-sm border border-slate-100 rounded-xl flex items-center justify-center text-emerald-600">
                    <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 6.253v13m0-13C10.832 5.477 9.246 5 7.5 5S4.168 5.477 3 6.253v13C4.168 18.477 5.754 18 7.5 18s3.332.477 4.5 1.253m0-13C13.168 5.477 14.754 5 16.5 5c1.747 0 3.332.477 4.5 1.253v13C19.832 18.477 18.247 18 16.5 18c-1.746 0-3.332.477-4.5 1.253" /></svg>
                  </div>
                  <div>
                    <h4 className="font-bold text-slate-800 text-xs uppercase tracking-wider">Format SCORM</h4>
                    <p className="text-[10px] text-slate-500 leading-tight">Dukungan paket interaktif ZIP (Manifest/HTML).</p>
                  </div>
                </div>
              </div>
            </div>

            {state.error && (
              <div className="p-4 bg-rose-50 border border-rose-100 rounded-xl text-rose-600 text-sm font-medium animate-bounce">{state.error}</div>
