import React, { useState } from 'react';
import { EvaluationReport, EvaluationStatus, ChatMessage } from '../types';
import { chatAboutReport } from '../services/geminiService';

interface ReportViewProps {
  report: EvaluationReport;
  onReset: () => void;
}

const ReportView: React.FC<ReportViewProps> = ({ report, onReset }) => {
  const [chatInput, setChatInput] = useState('');
  const [chatHistory, setChatHistory] = useState<ChatMessage[]>([]);
  const [isTyping, setIsTyping] = useState(false);

  const getStatusColor = (status: EvaluationStatus) => {
    switch (status) {
      case EvaluationStatus.PASS: return 'bg-emerald-100 text-emerald-700 border-emerald-200';
      case EvaluationStatus.FAIL: return 'bg-rose-100 text-rose-700 border-rose-200';
      case EvaluationStatus.WARNING: return 'bg-amber-100 text-amber-700 border-amber-200';
      default: return 'bg-slate-100 text-slate-700 border-slate-200';
    }
  };

  const downloadReportTxt = () => {
    let content = `LAPORAN EVALUASI SMARTASET\n`;
    content += `==========================\n\n`;
    content += `Nama Aset: ${report.assetName}\n`;
    content += `Skor Keseluruhan: ${report.overallScore}\n`;
    content += `Ringkasan: ${report.summary}\n\n`;
    content += `DETAIL TEMUAN:\n`;
    report.details.forEach(d => {
      content += `- ${d.criterion} [${d.status}]: ${d.finding}\n`;
      content += `  Rekomendasi: ${d.recommendation}\n\n`;
    });
    content += `KESALAHAN PENULISAN:\n`;
    report.typosFound.forEach(t => content += `- ${t}\n`);

    const blob = new Blob([content], { type: 'text/plain' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `SmartAset_Report_${report.assetName.replace(/\s+/g, '_')}.txt`;
    a.click();
  };

  const downloadReportPdf = async () => {
    // @ts-ignore
    const { jsPDF } = window.jspdf;
    const doc = new jsPDF();

    // Header
    doc.setFont("helvetica", "bold");
    doc.setFontSize(18);
    doc.setTextColor(5, 150, 105); // Emerald 600
    doc.text("Laporan Evaluasi SmartAset", 20, 20);

    doc.setFontSize(10);
    doc.setTextColor(100, 116, 139); // Slate 500
    doc.text(`Dicetak pada: ${new Date().toLocaleString('id-ID')}`, 20, 28);

    doc.setDrawColor(226, 232, 240); // Slate 200
    doc.line(20, 32, 190, 32);

    // Summary Section
    doc.setFontSize(12);
    doc.setTextColor(15, 23, 42); // Slate 900
    doc.text(`Nama Aset: ${report.assetName}`, 20, 42);
    doc.text(`Skor Aset: ${report.overallScore}/100`, 20, 50);

    doc.setFont("helvetica", "normal");
    const splitSummary = doc.splitTextToSize(`Ringkasan: ${report.summary}`, 170);
    doc.text(splitSummary, 20, 58);

    let y = 58 + (splitSummary.length * 6) + 10;

    // Findings Section
    doc.setFont("helvetica", "bold");
    doc.text("Detail Temuan Evaluasi:", 20, y);
    y += 8;

    report.details.forEach(d => {
      if (y > 260) { doc.addPage(); y = 20; }

      doc.setFont("helvetica", "bold");
      doc.setFontSize(11);
      doc.text(`• ${d.criterion} (${d.status})`, 20, y);
      y += 6;

      doc.setFont("helvetica", "normal");
      doc.setFontSize(10);
      const splitFinding = doc.splitTextToSize(`Temuan: ${d.finding}`, 160);
      doc.text(splitFinding, 25, y);
      y += (splitFinding.length * 5) + 2;

      doc.setFont("helvetica", "italic");
      doc.setTextColor(5, 150, 105);
      const splitRec = doc.splitTextToSize(`Saran Perbaikan: ${d.recommendation}`, 160);
      doc.text(splitRec, 25, y);
      y += (splitRec.length * 5) + 6;
      doc.setTextColor(15, 23, 42);
    });

    // Typos Section
    if (y > 260) { doc.addPage(); y = 20; }
    y += 4;
    doc.setFont("helvetica", "bold");
    doc.text("Kesalahan Penulisan (Typo/KBBI):", 20, y);
    y += 8;
    doc.setFont("helvetica", "normal");
    report.typosFound.forEach(t => {
      if (y > 275) { doc.addPage(); y = 20; }
      doc.text(`- ${t}`, 25, y);
      y += 6;
    });

    doc.save(`SmartAset_Report_${report.assetName}.pdf`);
  };

  const handleChat = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!chatInput.trim()) return;

    const newUserMsg: ChatMessage = { role: 'user', text: chatInput };
    setChatHistory(prev => [...prev, newUserMsg]);
    setChatInput('');
    setIsTyping(true);

    try {
      const response = await chatAboutReport(report, chatInput, chatHistory);
      setChatHistory(prev => [...prev, { role: 'model', text: response }]);
    } catch (err) {
      setChatHistory(prev => [...prev, { role: 'model', text: "Maaf, sepertinya ada sedikit gangguan saat menghubungi AI." }]);
    } finally {
      setIsTyping(false);
    }
  };

  return (
    <div className="max-w-7xl mx-auto space-y-8 pb-20">
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
        <h2 className="text-3xl font-black text-slate-900 tracking-tight">Hasil Analisis</h2>
        <div className="flex flex-wrap gap-2">
          <button onClick={downloadReportTxt} className="px-4 py-2 bg-white border border-slate-200 text-slate-700 rounded-lg flex items-center gap-2 hover:bg-slate-50 transition-all font-medium text-sm">
            <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-4l-4 4m0 0l-4-4m4 4V4" /></svg>
            Download Catatan (.txt)
          </button>
          <button onClick={downloadReportPdf} className="px-4 py-2 bg-emerald-600 text-white rounded-lg flex items-center gap-2 hover:bg-emerald-700 transition-all font-medium text-sm shadow-sm">
            <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M7 21h10a2 2 0 002-2V9.414a1 1 0 00-.293-.707l-5.414-5.414A1 1 0 0012.586 3H7a2 2 0 00-2 2v14a2 2 0 002 2z" /></svg>
            Cetak PDF Laporan
          </button>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
        {/* Left Column: Report Details */}
        <div className="lg:col-span-2 space-y-8">
          <div className="bg-white rounded-2xl shadow-sm border border-slate-200 overflow-hidden">
            <div className="p-8 space-y-4">
              <div className="flex justify-between items-start">
                <div className="space-y-1">
                  <h3 className="text-2xl font-bold text-slate-900">{report.assetName}</h3>
                  <p className="text-slate-500">{report.summary}</p>
                </div>
                <div className="bg-slate-50 px-6 py-4 rounded-2xl border border-slate-100 text-center">
                  <div className="text-xs font-bold text-slate-400 uppercase mb-1">Skor Aset</div>
                  <div className={`text-4xl font-black ${report.overallScore >= 80 ? 'text-emerald-600' : 'text-amber-500'}`}>{report.overallScore}</div>
                </div>
              </div>
            </div>
            <div className="grid grid-cols-3 border-t border-slate-100 divide-x divide-slate-100">
              <div className="p-4 text-center">
                <div className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">Logo</div>
                <div className={`text-sm font-bold ${report.logoDetected ? 'text-emerald-600' : 'text-rose-600'}`}>{report.logoDetected ? 'OK' : 'MISSING'}</div>
              </div>
              <div className="p-4 text-center">
                <div className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">Panduan</div>
                <div className={`text-sm font-bold ${report.userGuidePresent ? 'text-emerald-600' : 'text-rose-600'}`}>{report.userGuidePresent ? 'OK' : 'MISSING'}</div>
              </div>
              <div className="p-4 text-center">
                <div className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">Linguistik</div>
                <div className="text-sm font-bold text-slate-800">{report.typosFound.length}</div>
              </div>
            </div>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            {report.details.map((detail, idx) => (
              <div key={idx} className="bg-white p-5 rounded-xl border border-slate-200 hover:shadow-md transition-shadow">
                <div className="flex justify-between items-center mb-4">
                  <h4 className="font-bold text-slate-800">{detail.criterion}</h4>
                  <span className={`px-2 py-0.5 rounded-full text-[10px] font-bold border ${getStatusColor(detail.status)}`}>{detail.status}</span>
                </div>
                <p className="text-sm text-slate-600 mb-4 leading-relaxed">{detail.finding}</p>
                <div className="p-3 bg-emerald-50 rounded-lg border border-emerald-100 border-l-4 border-l-emerald-500">
                  <p className="text-xs text-emerald-800 italic">"Saran Ahli: {detail.recommendation}"</p>
                </div>
              </div>
            ))}
          </div>
        </div>

        {/* Right Column: AI Chat Assistant */}
        <div className="lg:col-span-1 space-y-6">
          <div className="bg-slate-900 rounded-2xl shadow-xl flex flex-col h-[600px] overflow-hidden">
            <div className="p-4 border-b border-slate-800 flex items-center gap-3">
              <div className="w-8 h-8 bg-emerald-500 rounded-lg flex items-center justify-center">
                <svg className="w-5 h-5 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M8 10h.01M12 10h.01M16 10h.01M9 16H5a2 2 0 01-2-2V6a2 2 0 012-2h14a2 2 0 012 2v8a2 2 0 01-2 2h-5l-5 5v-5z" /></svg>
