export enum EvaluationStatus {
  PASS = 'PASS',
  FAIL = 'FAIL',
  WARNING = 'WARNING'
}

export interface EvaluationDetail {
  criterion: string;
  status: EvaluationStatus;
  finding: string;
  recommendation: string;
}

export interface EvaluationReport {
  id: string;
  timestamp: number;
  assetName: string;
  overallScore: number;
  logoDetected: boolean;
  userGuidePresent: boolean;
  videoAudit: {
    openingValid: boolean;
    closingValid: boolean;
    durationOk: boolean;
  };
  typosFound: string[];
  details: EvaluationDetail[];
  summary: string;
}

export interface ChatMessage {
  role: 'user' | 'model';
  text: string;
}

export interface AppState {
  view: 'home' | 'report' | 'history' | 'guideline';
  files: {
    pdf: File | null;
    scorm: File | null;
    videoOpening: File | null;
    videoClosing: File | null;
  };
  isAnalyzing: boolean;
  report: EvaluationReport | null;
  history: EvaluationReport[];
  error: string | null;
  progress: number;
  chatHistory: ChatMessage[];
  isChatting: boolean;
}

import { GoogleGenAI, Type } from "@google/genai";
import { EvaluationReport, ChatMessage } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export async function analyzeLearningAsset(
  input: { 
    imageParts?: { inlineData: { data: string; mimeType: string } }[], 
    textContext?: string,
    videoOpeningFrames?: { inlineData: { data: string; mimeType: string } }[],
    videoClosingFrames?: { inlineData: { data: string; mimeType: string } }[]
  },
  fileName: string
): Promise<EvaluationReport> {
  const model = "gemini-3-flash-preview";

  const systemInstruction = `
    Anda adalah Pengembang Teknologi Pembelajaran (PTP) Ahli & Auditor Kualitas Aset Belajar Kemenkes.
    Tugas: Audit komprehensif 13 ASPEK berdasarkan PDF, SCORM, dan Video yang diberikan.

    KRITERIA KHUSUS VIDEO (OPENING & CLOSING):
    1. VIDEO OPENING (MAX 60 DETIK):
       - Harus ada presenter (Nama, Jabatan, Instansi).
       - Sapaan: "ASN Pembelajar" atau "Sahabat Pembelajar".
       - Isi: Nama materi, tujuan, relevansi tugas harian, kalimat penyemangat.
       - Gaya: Formal, inspiratif, semangat melayani.
    2. VIDEO CLOSING:
       - Isi: Rangkuman, pesan kunci (key messages).
       - Call to Action: Terima kasih & ajakan beralih ke materi selanjutnya.
       - LAYAR PENUTUP: WAJIB ada Identitas Bapelkes Cikarang (Nama, Lokasi, Website, Medsos).

    ANALISIS 13 ASPEK PEDOMAN:
    1. Logo (Kemenkes, Bapelkes, ZI, BerAKHLAK) - Gunakan deskripsi visual presisi.
    2. Standar Visual (VAG Rounded, Palet Kemenkes).
    3. Video Pengantar & Penutup (Sesuai kriteria naskah & durasi).
    4. Tim Penyusun (PJ, WI/Ahli, Pengembang Media).
    5. Panduan Penggunaan.
    6. Hasil Belajar.
    7. Indikator.
    8. Jabaran Materi.
    9. Materi Pokok (Interaktif).
    10. Refleksi (Sekarang Saya Tahu).
    11. Progress Bar.
    12. Kualitas Bahasa (PUEBI/KBBI Pedantik).
    13. Typo/Kesalahan Tanda Baca/Spasi Ganda.

    OUTPUT: JSON sesuai schema. Kurangi skor drastis jika Video Opening > 60s atau Layar Penutup tidak lengkap.
  `;

  const responseSchema = {
    type: Type.OBJECT,
    properties: {
      assetName: { type: Type.STRING },
      overallScore: { type: Type.NUMBER },
      logoDetected: { type: Type.BOOLEAN },
      userGuidePresent: { type: Type.BOOLEAN },
      videoAudit: {
        type: Type.OBJECT,
        properties: {
          openingValid: { type: Type.BOOLEAN },
          closingValid: { type: Type.BOOLEAN },
          durationOk: { type: Type.BOOLEAN }
        },
        required: ["openingValid", "closingValid", "durationOk"]
      },
      typosFound: { type: Type.ARRAY, items: { type: Type.STRING } },
      details: {
        type: Type.ARRAY,
        items: {
          type: Type.OBJECT,
          properties: {
            criterion: { type: Type.STRING },
            status: { type: Type.STRING },
            finding: { type: Type.STRING },
            recommendation: { type: Type.STRING }
          },
          required: ["criterion", "status", "finding", "recommendation"]
        }
      },
      summary: { type: Type.STRING }
    },
    required: ["assetName", "overallScore", "logoDetected", "userGuidePresent", "videoAudit", "typosFound", "details", "summary"]
  };

  const parts: any[] = [];
  if (input.imageParts) parts.push(...input.imageParts);
  if (input.textContext) parts.push({ text: input.textContext });
  if (input.videoOpeningFrames) {
    parts.push({ text: "BERIKUT FRAME DARI VIDEO OPENING:" });
    parts.push(...input.videoOpeningFrames);
  }
  if (input.videoClosingFrames) {
    parts.push({ text: "BERIKUT FRAME DARI VIDEO CLOSING:" });
    parts.push(...input.videoClosingFrames);
  }

  parts.push({ text: `Evaluasi Aset: ${fileName}. Berikan audit mendalam pada video, logo, dan teks KBBI.` });

  const response = await ai.models.generateContent({
    model: model,
    contents: [{ parts }],
    config: {
      systemInstruction: systemInstruction,
      responseMimeType: "application/json",
      responseSchema: responseSchema,
    },
  });

  const result = JSON.parse(response.text);
  return { ...result, id: crypto.randomUUID(), timestamp: Date.now() };
}

export async function chatAboutReport(
  report: EvaluationReport,
  userMessage: string,
  history: ChatMessage[]
): Promise<string> {
  const model = "gemini-3-flash-preview";
  const chat = ai.chats.create({
    model: model,
    config: {
      systemInstruction: `Anda asisten SmartAset. Bantu PTP memahami hasil audit 13 aspek. 
      Jika video tidak sesuai (misal durasi > 60 detik), tekankan pentingnya efektivitas microlearning.`
    }
  });

  const response = await chat.sendMessage({ message: userMessage });
  return response.text || "Terjadi kendala teknis.";
}

import React, { useState, useRef, useEffect } from 'react';
import Header from './components/Header';
import ReportView from './components/ReportView';
import GuidelineView from './components/GuidelineView';
import { AppState, EvaluationReport } from './types';
import { analyzeLearningAsset } from './services/geminiService';

// @ts-ignore
const pdfjsLib = window['pdfjs-dist/build/pdf'];
pdfjsLib.GlobalWorkerOptions.workerSrc = 'https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.worker.min.js';
// @ts-ignore
const JSZip = window.JSZip;

const App: React.FC = () => {
  const [state, setState] = useState<AppState>({
    view: 'home',
    files: { pdf: null, scorm: null, videoOpening: null, videoClosing: null },
    isAnalyzing: false,
    report: null,
    history: [],
    error: null,
    progress: 0,
    chatHistory: [],
    isChatting: false
  });

  useEffect(() => {
    const saved = localStorage.getItem('smartaset_history');
    if (saved) {
      try { setState(prev => ({ ...prev, history: JSON.parse(saved) })); } 
      catch (e) { console.error("History parse failed"); }
    }
  }, []);

  const saveToHistory = (report: EvaluationReport) => {
    const updatedHistory = [report, ...state.history].slice(0, 10);
    setState(prev => ({ ...prev, history: updatedHistory }));
    localStorage.setItem('smartaset_history', JSON.stringify(updatedHistory));
  };

  const extractFramesFromVideo = async (file: File): Promise<{ inlineData: { data: string, mimeType: string } }[]> => {
    return new Promise((resolve) => {
      const video = document.createElement('video');
      video.preload = 'metadata';
      video.src = URL.createObjectURL(file);
      video.muted = true;

      video.onloadedmetadata = () => {
        const frames: { inlineData: { data: string, mimeType: string } }[] = [];
        const captureTimes = [1, video.duration / 2, video.duration - 1]; // Start, middle, end
        let captured = 0;

        const capture = () => {
          const canvas = document.createElement('canvas');
          canvas.width = video.videoWidth;
          canvas.height = video.videoHeight;
          const ctx = canvas.getContext('2d');
          ctx?.drawImage(video, 0, 0);
          frames.push({ inlineData: { data: canvas.toDataURL('image/jpeg', 0.7).split(',')[1], mimeType: 'image/jpeg' } });
          captured++;

          if (captured < captureTimes.length) {
            video.currentTime = captureTimes[captured];
          } else {
            resolve(frames);
          }
        };

        video.onseeked = capture;
        video.currentTime = captureTimes[0];
      };
    });
  };

  const handleFileUpload = (type: keyof AppState['files'], file: File | null) => {
    setState(prev => ({
      ...prev,
      files: { ...prev.files, [type]: file },
      error: null
    }));
  };

  const startAnalysis = async () => {
    if (!state.files.pdf && !state.files.scorm) {
      setState(prev => ({ ...prev, error: "Minimal unggah PDF Aset atau SCORM Package." }));
      return;
    }

    setState(prev => ({ ...prev, isAnalyzing: true, progress: 10 }));

    try {
      let imageParts = [];
      let textContext = "";
      let videoOpeningFrames = [];
      let videoClosingFrames = [];

      // Process PDF
      if (state.files.pdf) {
        const arrayBuffer = await state.files.pdf.arrayBuffer();
        const pdf = await pdfjsLib.getDocument({ data: arrayBuffer }).promise;
        for (let i = 1; i <= Math.min(pdf.numPages, 5); i++) {
          const page = await pdf.getPage(i);
          const viewport = page.getViewport({ scale: 1.2 });
          const canvas = document.createElement('canvas');
          canvas.height = viewport.height;
          canvas.width = viewport.width;
          await page.render({ canvasContext: canvas.getContext('2d')!, viewport }).promise;
          imageParts.push({ inlineData: { data: canvas.toDataURL('image/jpeg', 0.7).split(',')[1], mimeType: 'image/jpeg' } });
        }
      }

      // Process SCORM
      if (state.files.scorm) {
        const zip = await JSZip.loadAsync(state.files.scorm);
        textContext = "Daftar File SCORM:\n";
        zip.forEach((path: string) => textContext += `- ${path}\n`);
        const manifest = await zip.file("imsmanifest.xml")?.async("string");
        if (manifest) textContext += `\nManifest:\n${manifest.substring(0, 1000)}`;
      }

      // Process Videos
      if (state.files.videoOpening) {
        videoOpeningFrames = await extractFramesFromVideo(state.files.videoOpening);
      }
      if (state.files.videoClosing) {
        videoClosingFrames = await extractFramesFromVideo(state.files.videoClosing);
      }

      setState(prev => ({ ...prev, progress: 60 }));

      const mainFileName = state.files.pdf?.name || state.files.scorm?.name || "Aset Belajar";
      const result = await analyzeLearningAsset({ 
        imageParts, 
        textContext, 
        videoOpeningFrames, 
        videoClosingFrames 
      }, mainFileName);

      saveToHistory(result);
      setState(prev => ({ ...prev, isAnalyzing: false, report: result, view: 'report', progress: 100 }));
    } catch (err) {
      console.error(err);
      setState(prev => ({ ...prev, isAnalyzing: false, error: "Gagal menganalisis. Pastikan format file sesuai." }));
    }
  };

  return (
    <div className="min-h-screen flex flex-col bg-slate-50">
      <Header onNavigate={(v) => setState(prev => ({ ...prev, view: v }))} activeView={state.view} />

      <main className="flex-grow max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-10 w-full">
        {state.isAnalyzing ? (
          <div className="max-w-xl mx-auto py-20 text-center space-y-8">
            <div className="w-20 h-20 border-4 border-slate-100 border-t-emerald-600 rounded-full animate-spin mx-auto"></div>
            <div className="space-y-4">
              <h3 className="text-xl font-black text-slate-800">Analisis Multi-Asset Berjalan...</h3>
              <div className="w-full bg-slate-200 h-1.5 rounded-full overflow-hidden">
                <div className="bg-emerald-600 h-full transition-all duration-300" style={{ width: `${state.progress}%` }}></div>
              </div>
              <p className="text-sm text-slate-500 italic">"Mengevaluasi PDF, SCORM, dan Video sesuai 13 aspek pedoman..."</p>
            </div>
          </div>
        ) : state.view === 'report' && state.report ? (
          <ReportView report={state.report} onReset={() => setState(prev => ({ ...prev, view: 'home', report: null, files: { pdf: null, scorm: null, videoOpening: null, videoClosing: null } }))} />
        ) : state.view === 'guideline' ? (
          <GuidelineView onNavigate={(v) => setState(prev => ({ ...prev, view: v }))} />
        ) : state.view === 'history' ? (
          <div className="max-w-4xl mx-auto py-10">
            <h2 className="text-2xl font-black text-slate-900 mb-6">Riwayat Audit</h2>
            <div className="grid gap-4">
              {state.history.map(item => (
                <div key={item.id} onClick={() => setState(prev => ({ ...prev, report: item, view: 'report' }))} className="bg-white p-5 rounded-2xl border border-slate-200 hover:border-emerald-400 cursor-pointer flex justify-between items-center group shadow-sm">
                  <div className="flex gap-4 items-center">
                    <div className="w-12 h-12 bg-emerald-50 text-emerald-600 rounded-xl flex items-center justify-center font-black text-lg group-hover:bg-emerald-600 group-hover:text-white transition-colors">{item.overallScore}</div>
                    <div>
                      <h4 className="font-bold text-slate-900">{item.assetName}</h4>
                      <p className="text-xs text-slate-500">{new Date(item.timestamp).toLocaleDateString('id-ID')}</p>
                    </div>
                  </div>
                  <svg className="w-5 h-5 text-slate-300 group-hover:text-emerald-500 transition-colors" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M9 5l7 7-7 7" /></svg>
                </div>
              ))}
            </div>
          </div>
