import { GoogleGenAI, Type } from "@google/genai";
import { EvaluationReport, ChatMessage } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export async function analyzeLearningAsset(
  input: { 
    imageParts?: { inlineData: { data: string; mimeType: string } }[], 
    textContext?: string,
    videoOpeningFrames?: { inlineData: { data: string; mimeType: string } }[],
    videoClosingFrames?: { inlineData: { data: string; mimeType: string } }[]
  },
  fileName: string
): Promise<EvaluationReport> {
  const model = "gemini-3-flash-preview";

  const systemInstruction = `
    Anda adalah AUDITOR SENIOR Pengembang Teknologi Pembelajaran (PTP) di Kemenkes RI.
    Tugas Anda adalah melakukan audit SANGAT DETAIL dan KRITIS terhadap aset pembelajaran berdasarkan 13 aspek pedoman.

    KRITERIA AUDIT YANG SANGAT KETAT:
    1. KUALITAS BAHASA (KBBI & PUEBI):
       - Cek setiap kata. Kritik jika ada: 'praktek' (harus praktik), 'analisa' (harus analisis), 'merubah' (harus mengubah).
       - Cek tanda baca: Spasi sebelum titik/koma adalah kesalahan fatal. Huruf kapital pada jabatan (Kepala Bapelkes) harus benar.
    2. VIDEO OPENING (DETAIL):
       - Harus menyebut "ASN Pembelajar" atau "Sahabat Pembelajar".
       - Harus menyebut Nama, Jabatan, Instansi presenter.
       - Harus ada tujuan belajar & relevansi tugas harian. Kritik jika durasi terasa terlalu cepat atau lambat.
    3. VIDEO CLOSING & LAYAR PENUTUP:
       - Harus ada ringkasan materi.
       - LAYAR PENUTUP WAJIB: Logo Bapelkes Cikarang, Alamat/Lokasi, Website, dan Media Sosial. Jika tidak ada salah satu, nyatakan GAGAL pada aspek ini.
    4. LOGO & VISUAL:
       - Logo BerAKHLAK, ZI, Kemenkes CorU, Bapelkes Cikarang.
       - Font: VAG Rounded. Warna: Palet Kemenkes (Tosca, Hijau Muda, Kuning).
    5. STRUKTUR 13 ASPEK:
       Audit mencakup: Logo, Visual, Video, Tim Penyusun, Panduan, Hasil Belajar, Indikator, Jabaran Materi, Materi Pokok, Refleksi, Progress Bar, Bahasa, Typo.

    PENTING: Jangan berikan jawaban umum. Berikan temuan spesifik: "Pada slide/halaman X, kata '...' tidak baku". Jika video tidak menyebutkan jabatan, berikan rekomendasi naskah yang benar.
  `;

  const responseSchema = {
    type: Type.OBJECT,
    properties: {
      assetName: { type: Type.STRING },
      overallScore: { type: Type.NUMBER },
      logoDetected: { type: Type.BOOLEAN },
      userGuidePresent: { type: Type.BOOLEAN },
      videoAudit: {
        type: Type.OBJECT,
        properties: {
          openingValid: { type: Type.BOOLEAN },
          closingValid: { type: Type.BOOLEAN },
          durationOk: { type: Type.BOOLEAN }
        },
        required: ["openingValid", "closingValid", "durationOk"]
      },
      typosFound: { type: Type.ARRAY, items: { type: Type.STRING } },
      details: {
        type: Type.ARRAY,
        items: {
          type: Type.OBJECT,
          properties: {
            criterion: { type: Type.STRING },
            status: { type: Type.STRING },
            finding: { type: Type.STRING },
            recommendation: { type: Type.STRING }
          },
          required: ["criterion", "status", "finding", "recommendation"]
        }
      },
      summary: { type: Type.STRING }
    },
    required: ["assetName", "overallScore", "logoDetected", "userGuidePresent", "videoAudit", "typosFound", "details", "summary"]
  };

  const parts: any[] = [];
  if (input.imageParts) parts.push(...input.imageParts);
  if (input.textContext) parts.push({ text: `KONTEN TEKS/SCORM:\n${input.textContext}` });
  if (input.videoOpeningFrames) {
    parts.push({ text: "VISUAL VIDEO OPENING (Gunakan untuk cek presenter & sapaan):" });
    parts.push(...input.videoOpeningFrames);
  }
  if (input.videoClosingFrames) {
    parts.push({ text: "VISUAL VIDEO CLOSING (Gunakan untuk cek layar penutup/medsos):" });
    parts.push(...input.videoClosingFrames);
  }

  parts.push({ text: `Audit file: ${fileName}. Lakukan analisis mendalam dan berikan saran perbaikan naskah jika diperlukan.` });

  const response = await ai.models.generateContent({
    model: model,
    contents: [{ parts }],
    config: {
      systemInstruction: systemInstruction,
      responseMimeType: "application/json",
      responseSchema: responseSchema,
      temperature: 0.2 // Lebih rendah agar lebih konsisten dan objektif
    },
  });

  const result = JSON.parse(response.text);
  return { ...result, id: crypto.randomUUID(), timestamp: Date.now() };
}

export async function chatAboutReport(
  report: EvaluationReport,
  userMessage: string,
  history: ChatMessage[]
): Promise<string> {
  const model = "gemini-3-flash-preview";
  const chat = ai.chats.create({
    model: model,
    config: {
      systemInstruction: `Anda adalah pakar PTP Kemenkes. Jawablah pertanyaan user terkait hasil audit secara teknis dan edukatif. Rujuklah pada aturan KBBI dan Pedoman Aset Pembelajaran.`
    }
  });

  const response = await chat.sendMessage({ message: userMessage });
  return response.text || "Terjadi kendala pada asisten AI.";
}

import React, { useState, useRef, useEffect } from 'react';
import Header from './components/Header';
import ReportView from './components/ReportView';
import GuidelineView from './components/GuidelineView';
import { AppState, EvaluationReport } from './types';
import { analyzeLearningAsset } from './services/geminiService';

// @ts-ignore
const pdfjsLib = window['pdfjs-dist/build/pdf'];
pdfjsLib.GlobalWorkerOptions.workerSrc = 'https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.worker.min.js';
// @ts-ignore
const JSZip = window.JSZip;

const App: React.FC = () => {
  const [state, setState] = useState<AppState>({
    view: 'home',
    files: { pdf: null, scorm: null, videoOpening: null, videoClosing: null },
    isAnalyzing: false,
    report: null,
    history: [],
    error: null,
    progress: 0,
    chatHistory: [],
    isChatting: false
  });

  useEffect(() => {
    const saved = localStorage.getItem('smartaset_history');
    if (saved) {
      try { setState(prev => ({ ...prev, history: JSON.parse(saved) })); } 
      catch (e) { console.error("History parse failed"); }
    }
  }, []);

  const saveToHistory = (report: EvaluationReport) => {
    const updatedHistory = [report, ...state.history].slice(0, 10);
    setState(prev => ({ ...prev, history: updatedHistory }));
    localStorage.setItem('smartaset_history', JSON.stringify(updatedHistory));
  };

  const extractFramesFromVideo = async (file: File): Promise<{ inlineData: { data: string, mimeType: string } }[]> => {
    return new Promise((resolve) => {
      const video = document.createElement('video');
      video.preload = 'metadata';
      video.src = URL.createObjectURL(file);
      video.muted = true;

      video.onloadedmetadata = () => {
        const frames: { inlineData: { data: string, mimeType: string } }[] = [];
        const captureTimes = [0.5, video.duration / 2, video.duration - 0.5];
        let captured = 0;

        const capture = () => {
          const canvas = document.createElement('canvas');
          canvas.width = video.videoWidth;
          canvas.height = video.videoHeight;
          const ctx = canvas.getContext('2d');
          ctx?.drawImage(video, 0, 0);
          frames.push({ inlineData: { data: canvas.toDataURL('image/jpeg', 0.8).split(',')[1], mimeType: 'image/jpeg' } });
          captured++;

          if (captured < captureTimes.length) {
            video.currentTime = captureTimes[captured];
          } else {
            resolve(frames);
          }
        };

        video.onseeked = capture;
        video.currentTime = captureTimes[0];
      };
    });
  };

  const handleFileUpload = (type: keyof AppState['files'], file: File | null) => {
    setState(prev => {
      const newFiles = { ...prev.files, [type]: file };
      // Exclusive logic: If PDF is selected, clear SCORM. If SCORM is selected, clear PDF.
      if (type === 'pdf' && file) newFiles.scorm = null;
      if (type === 'scorm' && file) newFiles.pdf = null;

      return {
        ...prev,
        files: newFiles,
        error: null
      };
    });
  };

  const startAnalysis = async () => {
    if (!state.files.pdf && !state.files.scorm) {
      setState(prev => ({ ...prev, error: "Silakan unggah Dokumen Aset (PDF) atau Paket SCORM terlebih dahulu." }));
      return;
    }

    setState(prev => ({ ...prev, isAnalyzing: true, progress: 10 }));

    try {
      let imageParts = [];
      let textContext = "";
      let videoOpeningFrames = [];
      let videoClosingFrames = [];

      // Deep Process PDF
      if (state.files.pdf) {
        const arrayBuffer = await state.files.pdf.arrayBuffer();
        const pdf = await pdfjsLib.getDocument({ data: arrayBuffer }).promise;
        const numToScan = Math.min(pdf.numPages, 10); // Scan up to 10 pages for better depth
        for (let i = 1; i <= numToScan; i++) {
          const page = await pdf.getPage(i);
          const viewport = page.getViewport({ scale: 1.5 });
          const canvas = document.createElement('canvas');
          canvas.height = viewport.height;
          canvas.width = viewport.width;
          await page.render({ canvasContext: canvas.getContext('2d')!, viewport }).promise;
          imageParts.push({ inlineData: { data: canvas.toDataURL('image/jpeg', 0.7).split(',')[1], mimeType: 'image/jpeg' } });

          // Also extract text for KBBI analysis
          const textContent = await page.getTextContent();
          textContext += textContent.items.map((item: any) => item.str).join(' ') + "\n";

          setState(prev => ({ ...prev, progress: 10 + Math.round((i / numToScan) * 40) }));
        }
      }

      // Deep Process SCORM
      if (state.files.scorm) {
        const zip = await JSZip.loadAsync(state.files.scorm);
        textContext = "AUDIT PAKET SCORM:\n";
        const manifest = await zip.file("imsmanifest.xml")?.async("string");
        if (manifest) textContext += `MANIFEST:\n${manifest}\n`;

        // Look for HTML content for text audit
        const htmlFiles = Object.keys(zip.files).filter(f => f.endsWith('.html') || f.endsWith('.htm')).slice(0, 5);
        for (const f of htmlFiles) {
          const content = await zip.file(f)?.async("string");
          if (content) textContext += `\nFILE CONTENT (${f}):\n${content.replace(/<[^>]*>?/gm, '').substring(0, 2000)}`;
        }
        setState(prev => ({ ...prev, progress: 50 }));
      }

      // Process Videos
      if (state.files.videoOpening) {
        videoOpeningFrames = await extractFramesFromVideo(state.files.videoOpening);
      }
      if (state.files.videoClosing) {
        videoClosingFrames = await extractFramesFromVideo(state.files.videoClosing);
      }

      setState(prev => ({ ...prev, progress: 75 }));

      const mainFileName = state.files.pdf?.name || state.files.scorm?.name || "Aset Belajar";
      const result = await analyzeLearningAsset({ 
        imageParts, 
        textContext, 
        videoOpeningFrames, 
        videoClosingFrames 
      }, mainFileName);

      saveToHistory(result);
      setState(prev => ({ ...prev, isAnalyzing: false, report: result, view: 'report', progress: 100 }));
    } catch (err) {
      console.error(err);
      setState(prev => ({ ...prev, isAnalyzing: false, error: "Analisis gagal. Pastikan file tidak korup dan format sesuai." }));
    }
  };

  return (
    <div className="min-h-screen flex flex-col bg-slate-50">
      <Header onNavigate={(v) => setState(prev => ({ ...prev, view: v }))} activeView={state.view} />

      <main className="flex-grow max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-10 w-full">
        {state.isAnalyzing ? (
          <div className="max-w-xl mx-auto py-20 text-center space-y-8">
            <div className="w-20 h-20 border-4 border-slate-100 border-t-emerald-600 rounded-full animate-spin mx-auto"></div>
            <div className="space-y-4">
              <h3 className="text-xl font-black text-slate-800 tracking-tight">Melakukan Audit Mendalam...</h3>
              <div className="w-full bg-slate-200 h-2 rounded-full overflow-hidden">
