              </div>
              <p className="text-sm text-slate-500 font-medium">Memeriksa 13 Aspek Pedoman & KBBI...</p>
            </div>
          </div>
        ) : state.view === 'report' && state.report ? (
          <ReportView report={state.report} onReset={() => setState(prev => ({ ...prev, view: 'home', report: null, files: { pdf: null, scorm: null, videoOpening: null, videoClosing: null } }))} />
        ) : state.view === 'guideline' ? (
          <GuidelineView onNavigate={(v) => setState(prev => ({ ...prev, view: v }))} />
        ) : state.view === 'history' ? (
