            <h2 className="text-2xl font-black text-slate-900 mb-6 tracking-tight">Riwayat Audit Komprehensif</h2>
            <div className="grid gap-4">
              {state.history.map(item => (
                <div key={item.id} onClick={() => setState(prev => ({ ...prev, report: item, view: 'report' }))} className="bg-white p-6 rounded-[2rem] border border-slate-200 hover:border-emerald-400 cursor-pointer flex justify-between items-center group shadow-sm transition-all hover:shadow-md">
                  <div className="flex gap-5 items-center">
                    <div className="w-14 h-14 bg-emerald-50 text-emerald-600 rounded-2xl flex items-center justify-center font-black text-xl group-hover:bg-emerald-600 group-hover:text-white transition-all shadow-inner">{item.overallScore}</div>
                    <div>
                      <h4 className="font-bold text-slate-900 leading-tight">{item.assetName}</h4>
                      <p className="text-xs text-slate-400 mt-1 font-medium">{new Date(item.timestamp).toLocaleDateString('id-ID', { day: 'numeric', month: 'long', year: 'numeric' })}</p>
                    </div>
                  </div>
                  <div className="flex items-center gap-2 text-emerald-600 opacity-0 group-hover:opacity-100 transition-opacity font-bold text-xs uppercase tracking-widest">
