        ) : (
          <div className="max-w-5xl mx-auto space-y-12 animate-in fade-in slide-in-from-bottom-4 duration-700">
            <div className="text-center space-y-4">
              <span className="px-4 py-1.5 bg-emerald-100 text-emerald-700 rounded-full text-[10px] font-black uppercase tracking-[0.2em]">PTP Audit Standard</span>
              <h2 className="text-4xl md:text-6xl font-black text-slate-900 tracking-tight leading-none">Evaluasi Aset <span className="text-emerald-600">Berbasis AI.</span></h2>
              <p className="text-lg text-slate-500 max-w-2xl mx-auto">Pilih salah satu sumber aset utama (PDF atau SCORM) untuk memulai audit kompleks 13 kategori.</p>
            </div>

            <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
              {/* Primary Content Selection */}
              <div className="lg:col-span-2 space-y-6">
                <div className="bg-white p-8 rounded-[2.5rem] border-2 border-slate-100 shadow-xl shadow-slate-200/40 space-y-8">
                  <div className="flex items-center justify-between border-b border-slate-50 pb-4">
                    <h3 className="font-black text-slate-900 text-lg uppercase tracking-tight">1. Sumber Konten Utama</h3>
                    <span className="text-[10px] text-amber-600 font-bold bg-amber-50 px-3 py-1 rounded-full uppercase">Pilih Salah Satu</span>
                  </div>

                  <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                    <div className={`relative p-6 rounded-3xl border-2 transition-all cursor-pointer group ${state.files.pdf ? 'border-emerald-500 bg-emerald-50/30' : 'border-slate-100 hover:border-slate-200'}`}>
                      <input type="file" accept=".pdf" onChange={(e) => handleFileUpload('pdf', e.target.files?.[0] || null)} className="absolute inset-0 opacity-0 cursor-pointer" />
                      <div className="flex flex-col items-center gap-4 text-center">
