                           <svg className="w-8 h-8" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M7 21h10a2 2 0 002-2V9.414a1 1 0 00-.293-.707l-5.414-5.414A1 1 0 0012.586 3H7a2 2 0 00-2 2v14a2 2 0 002 2z" /></svg>
                        </div>
                        <div>
                          <h4 className="font-bold text-slate-900">Dokumen PDF</h4>
                          <p className="text-[10px] text-slate-400 font-medium">{state.files.pdf ? state.files.pdf.name : 'Format .pdf'}</p>
                        </div>
                      </div>
                    </div>

                    <div className={`relative p-6 rounded-3xl border-2 transition-all cursor-pointer group ${state.files.scorm ? 'border-emerald-500 bg-emerald-50/30' : 'border-slate-100 hover:border-slate-200'}`}>
                      <input type="file" accept=".zip" onChange={(e) => handleFileUpload('scorm', e.target.files?.[0] || null)} className="absolute inset-0 opacity-0 cursor-pointer" />
                      <div className="flex flex-col items-center gap-4 text-center">
                        <div className={`w-14 h-14 rounded-2xl flex items-center justify-center transition-all ${state.files.scorm ? 'bg-emerald-600 text-white' : 'bg-blue-50 text-blue-500 group-hover:scale-110'}`}>
                           <svg className="w-8 h-8" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M20 7l-8-4-8 4m16 0l-8 4m8-4v10l-8 4m0-10L4 7m8 4v10M4 7v10l8 4" /></svg>
