                       <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest block">Video Pengantar (Opening)</label>
                       <input type="file" accept="video/*" onChange={(e) => handleFileUpload('videoOpening', e.target.files?.[0] || null)} className="w-full text-xs text-slate-500 file:mr-3 file:py-2 file:px-4 file:rounded-xl file:border-0 file:text-[10px] file:font-black file:bg-emerald-50 file:text-emerald-700 hover:file:bg-emerald-100 cursor-pointer" />
                       <p className="text-[9px] text-slate-400 italic">Cek Presenter, Sapaan ASN, Durasi &lt; 60s</p>
                    </div>
                    <div className="space-y-2">
                       <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest block">Video Penutup (Closing)</label>
                       <input type="file" accept="video/*" onChange={(e) => handleFileUpload('videoClosing', e.target.files?.[0] || null)} className="w-full text-xs text-slate-500 file:mr-3 file:py-2 file:px-4 file:rounded-xl file:border-0 file:text-[10px] file:font-black file:bg-emerald-50 file:text-emerald-700 hover:file:bg-emerald-100 cursor-pointer" />
                       <p className="text-[9px] text-slate-400 italic">Cek Layar Penutup & Info Medsos Bapelkes</p>
                    </div>
                  </div>
                </div>
              </div>
            </div>

            <div className="flex flex-col items-center gap-6">
              <button 
                onClick={startAnalysis}
                disabled={state.isAnalyzing}
                className="group relative w-full max-w-xl py-6 bg-slate-900 text-white text-2xl font-black rounded-[2.5rem] shadow-2xl shadow-slate-400 hover:bg-emerald-600 transition-all disabled:opacity-50 overflow-hidden"
              >
                <span className="relative z-10">MULAI AUDIT KOMPREHENSIF</span>
                <div className="absolute inset-0 bg-emerald-600 translate-y-full group-hover:translate-y-0 transition-transform duration-500"></div>
              </button>
              {state.error && <p className="px-6 py-3 bg-rose-50 text-rose-600 font-bold rounded-2xl border border-rose-100 animate-bounce text-sm">{state.error}</p>}
            </div>
          </div>
        )}
      </main>

      <footer className="py-12 border-t border-slate-100 text-center">
         <div className="max-w-7xl mx-auto px-4 flex flex-col items-center gap-4">
            <div className="flex items-center gap-2 opacity-30">
               <div className="w-2 h-2 bg-emerald-500 rounded-full"></div>
               <div className="w-2 h-2 bg-emerald-500 rounded-full"></div>
               <div className="w-2 h-2 bg-emerald-500 rounded-full"></div>
            </div>
            <p className="text-[10px] text-slate-300 font-black uppercase tracking-[0.4em]">SmartAset v3.0 • Auditor Teknologi Pembelajaran</p>
