  );
};

export default App;

import React, { useState } from 'react';
import { EvaluationReport, EvaluationStatus, ChatMessage } from '../types';
import { chatAboutReport } from '../services/geminiService';

interface ReportViewProps {
  report: EvaluationReport;
  onReset: () => void;
}

const ReportView: React.FC<ReportViewProps> = ({ report, onReset }) => {
  const [chatInput, setChatInput] = useState('');
  const [chatHistory, setChatHistory] = useState<ChatMessage[]>([]);
  const [isTyping, setIsTyping] = useState(false);

  const getStatusColor = (status: string) => {
    switch (status.toUpperCase()) {
      case 'PASS': return 'bg-emerald-100 text-emerald-700 border-emerald-200';
      case 'FAIL': return 'bg-rose-100 text-rose-700 border-rose-200';
      case 'WARNING': return 'bg-amber-100 text-amber-700 border-amber-200';
      default: return 'bg-slate-100 text-slate-700 border-slate-200';
    }
  };

  const downloadReportTxt = () => {
    let content = `HASIL AUDIT KOMPREHENSIF SMARTASET v3.0\n`;
    content += `=========================================\n`;
    content += `Aset: ${report.assetName}\n`;
    content += `Skor: ${report.overallScore}/100\n`;
    content += `Waktu Audit: ${new Date(report.timestamp).toLocaleString('id-ID')}\n\n`;

    content += `RINGKASAN EKSEKUTIF:\n${report.summary}\n\n`;

    content += `AUDIT VIDEO:\n`;
    content += `- Video Opening: ${report.videoAudit.openingValid ? 'VALID' : 'TIDAK VALID'}\n`;
    content += `- Video Closing: ${report.videoAudit.closingValid ? 'VALID' : 'TIDAK VALID'}\n`;
    content += `- Durasi Total: ${report.videoAudit.durationOk ? 'SESUAI PEDOMAN (<60s)' : 'MELEBIHI BATAS'}\n\n`;

    content += `TEMUAN DETAIL (13 ASPEK):\n`;
    report.details.forEach((d, i) => {
      content += `${i+1}. ${d.criterion.toUpperCase()}\n`;
      content += `   Status: ${d.status}\n`;
      content += `   Temuan: ${d.finding}\n`;
      content += `   Saran: ${d.recommendation}\n\n`;
    });

    if (report.typosFound.length > 0) {
      content += `DAFTAR KESALAHAN TULIS/KBBI:\n`;
      report.typosFound.forEach(t => content += `- ${t}\n`);
    }

    const blob = new Blob([content], { type: 'text/plain' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `SmartAset_Audit_${report.assetName.replace(/\s+/g, '_')}.txt`;
    a.click();
    URL.revokeObjectURL(url);
  };

  const downloadReportPdf = () => {
    // @ts-ignore
    const { jsPDF } = window.jspdf;
    const doc = new jsPDF();
    let y = 20;

    // Header Styling
    doc.setFillColor(15, 23, 42); // Slate 900
    doc.rect(0, 0, 210, 40, 'F');
    doc.setTextColor(255, 255, 255);
    doc.setFontSize(22);
    doc.setFont("helvetica", "bold");
    doc.text("LAPORAN AUDIT SMARTASET", 20, 25);
    doc.setFontSize(10);
    doc.setFont("helvetica", "normal");
    doc.text(`Evaluator Aset Pembelajaran Kemenkes RI • v3.0`, 20, 32);

    y = 55;
    doc.setTextColor(15, 23, 42);
    doc.setFontSize(16);
    doc.setFont("helvetica", "bold");
    doc.text(report.assetName, 20, y);
    y += 8;
    doc.setFontSize(10);
    doc.setTextColor(100, 116, 139);
    doc.text(`Dicetak: ${new Date().toLocaleString('id-ID')}`, 20, y);

    // Score Badge
    doc.setFillColor(241, 245, 249);
    doc.roundedRect(160, 45, 35, 25, 3, 3, 'F');
    doc.setTextColor(16, 185, 129); // Emerald 600
    doc.setFontSize(24);
    doc.text(`${report.overallScore}`, 177.5, 63, { align: "center" });
    doc.setFontSize(8);
    doc.setTextColor(100, 116, 139);
    doc.text("TOTAL SKOR", 177.5, 52, { align: "center" });

    y += 15;
    doc.setTextColor(15, 23, 42);
    doc.setFontSize(12);
    doc.setFont("helvetica", "bold");
    doc.text("Ringkasan Eksekutif:", 20, y);
    y += 6;
    doc.setFont("helvetica", "normal");
    doc.setFontSize(10);
    const summaryLines = doc.splitTextToSize(report.summary, 170);
    doc.text(summaryLines, 20, y);
    y += (summaryLines.length * 5) + 10;

    // 13 Aspects Section
    doc.setFont("helvetica", "bold");
    doc.setFontSize(12);
    doc.text("Detail Audit 13 Aspek Pedoman:", 20, y);
    y += 10;

    report.details.forEach((d, i) => {
      if (y > 260) { doc.addPage(); y = 20; }

      doc.setFont("helvetica", "bold");
      doc.setFontSize(10);
      doc.text(`${i+1}. ${d.criterion} (${d.status})`, 20, y);
      y += 6;

      doc.setFont("helvetica", "normal");
      doc.setFontSize(9);
      doc.setTextColor(71, 85, 105);
      const findingLines = doc.splitTextToSize(`Temuan: ${d.finding}`, 165);
      doc.text(findingLines, 25, y);
      y += (findingLines.length * 5) + 2;

      doc.setTextColor(5, 150, 105);
      doc.setFont("helvetica", "italic");
      const recLines = doc.splitTextToSize(`Rekomendasi: ${d.recommendation}`, 165);
      doc.text(recLines, 25, y);
      y += (recLines.length * 5) + 6;
      doc.setTextColor(15, 23, 42);
    });

    if (report.typosFound.length > 0) {
      if (y > 240) { doc.addPage(); y = 20; }
      y += 5;
      doc.setFont("helvetica", "bold");
      doc.setFontSize(11);
      doc.text("Daftar Kesalahan KBBI/Tulisan:", 20, y);
      y += 8;
      doc.setFont("helvetica", "normal");
      doc.setFontSize(9);
      report.typosFound.forEach(t => {
        if (y > 275) { doc.addPage(); y = 20; }
        doc.text(`• ${t}`, 25, y);
        y += 5;
      });
    }

    doc.save(`Audit_SmartAset_${report.assetName}.pdf`);
  };

  const handleChat = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!chatInput.trim()) return;

    const newUserMsg: ChatMessage = { role: 'user', text: chatInput };
    setChatHistory(prev => [...prev, newUserMsg]);
    setChatInput('');
    setIsTyping(true);

    try {
      const response = await chatAboutReport(report, chatInput, chatHistory);
      setChatHistory(prev => [...prev, { role: 'model', text: response }]);
    } catch (err) {
      setChatHistory(prev => [...prev, { role: 'model', text: "Terjadi kesalahan saat menghubungi auditor AI." }]);
    } finally {
      setIsTyping(false);
    }
  };

  return (
    <div className="max-w-7xl mx-auto space-y-8 pb-20 animate-in fade-in duration-500">
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
        <div>
          <h2 className="text-3xl font-black text-slate-900 tracking-tight">Audit Komprehensif Selesai</h2>
          <p className="text-slate-400 text-sm font-medium">Laporan dihasilkan secara otomatis berdasarkan 13 Kategori Pedoman PTP.</p>
        </div>
        <div className="flex flex-wrap gap-3 w-full md:w-auto">
          <button onClick={downloadReportTxt} className="flex-1 md:flex-none px-6 py-3 bg-white border border-slate-200 text-slate-700 rounded-2xl flex items-center justify-center gap-2 hover:bg-slate-50 transition-all font-bold text-xs uppercase tracking-widest shadow-sm">
            <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-4l-4 4m0 0l-4-4m4 4V4" /></svg>
            Export .TXT
          </button>
          <button onClick={downloadReportPdf} className="flex-1 md:flex-none px-6 py-3 bg-emerald-600 text-white rounded-2xl flex items-center justify-center gap-2 hover:bg-emerald-700 transition-all font-bold text-xs uppercase tracking-widest shadow-xl shadow-emerald-900/10">
            <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M7 21h10a2 2 0 002-2V9.414a1 1 0 00-.293-.707l-5.414-5.414A1 1 0 0012.586 3H7a2 2 0 00-2 2v14a2 2 0 002 2z" /></svg>
            Download PDF
          </button>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
        <div className="lg:col-span-2 space-y-8">
          {/* Main Score Card */}
          <div className="bg-white rounded-[2.5rem] shadow-sm border border-slate-200 p-10 space-y-8 overflow-hidden relative">
            <div className="absolute top-0 right-0 w-32 h-32 bg-emerald-50 rounded-bl-[5rem] -mr-16 -mt-16 opacity-50"></div>

            <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-6 relative z-10">
              <div className="space-y-3 flex-1">
                <div className="flex items-center gap-3">
                   <span className="px-3 py-1 bg-slate-900 text-white text-[9px] font-black rounded-full uppercase tracking-widest">Target Audit</span>
                   <h3 className="text-2xl font-black text-slate-900">{report.assetName}</h3>
                </div>
                <p className="text-slate-500 leading-relaxed font-medium">{report.summary}</p>
              </div>
              <div className="text-center bg-white px-10 py-6 rounded-[2rem] border-2 border-slate-50 shadow-inner min-w-[140px]">
                <div className="text-[10px] font-black text-slate-300 uppercase tracking-widest mb-1">Total Skor</div>
                <div className={`text-6xl font-black ${report.overallScore >= 80 ? 'text-emerald-600' : 'text-amber-500'}`}>{report.overallScore}</div>
              </div>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-3 gap-6 pt-8 border-t border-slate-50">
               <div className="p-5 bg-slate-50/50 rounded-3xl border border-slate-100 space-y-2">
                  <div className="text-[10px] font-black text-slate-400 uppercase tracking-wider">Audit Video</div>
                  <div className="flex flex-col gap-1">
                    <div className="flex items-center justify-between">
                       <span className="text-[11px] font-bold text-slate-500">Opening</span>
                       <span className={`text-[10px] font-black ${report.videoAudit.openingValid ? 'text-emerald-600' : 'text-rose-600'}`}>{report.videoAudit.openingValid ? 'PASSED' : 'FAILED'}</span>
                    </div>
                    <div className="flex items-center justify-between">
                       <span className="text-[11px] font-bold text-slate-500">Closing</span>
                       <span className={`text-[10px] font-black ${report.videoAudit.closingValid ? 'text-emerald-600' : 'text-rose-600'}`}>{report.videoAudit.closingValid ? 'PASSED' : 'FAILED'}</span>
                    </div>
                  </div>
               </div>
               <div className="p-5 bg-slate-50/50 rounded-3xl border border-slate-100 space-y-2 text-center flex flex-col justify-center">
                  <div className="text-[10px] font-black text-slate-400 uppercase tracking-wider">Durasi Video</div>
                  <div className={`text-sm font-black ${report.videoAudit.durationOk ? 'text-emerald-600' : 'text-rose-600'}`}>
                    {report.videoAudit.durationOk ? 'SESUAI (<60s)' : 'NON-STANDAR'}
                  </div>
               </div>
               <div className="p-5 bg-slate-50/50 rounded-3xl border border-slate-100 space-y-2 text-center flex flex-col justify-center">
                  <div className="text-[10px] font-black text-slate-400 uppercase tracking-wider">Kesalahan Tulis</div>
                  <div className="text-xl font-black text-slate-800">{report.typosFound.length} <span className="text-[10px] text-slate-400">TEMUAN</span></div>
               </div>
            </div>
          </div>

          {/* Findings Feed */}
          <div className="space-y-6">
             <h4 className="text-sm font-black text-slate-400 uppercase tracking-[0.3em] pl-2">Detail Temuan Per-Aspek</h4>
             <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                {report.details.map((detail, idx) => (
                  <div key={idx} className="bg-white p-8 rounded-[2rem] border border-slate-200 hover:shadow-xl transition-all border-l-8 border-l-emerald-500 flex flex-col h-full">
                    <div className="flex justify-between items-start mb-4">
                      <h5 className="font-black text-slate-900 text-sm leading-tight max-w-[70%]">{detail.criterion}</h5>
                      <span className={`px-3 py-1 rounded-full text-[9px] font-black border uppercase tracking-widest ${getStatusColor(detail.status)}`}>{detail.status}</span>
                    </div>
                    <p className="text-xs text-slate-500 mb-6 leading-relaxed flex-grow">{detail.finding}</p>
                    <div className="p-4 bg-emerald-50 rounded-2xl border border-emerald-100">
                      <div className="text-[8px] font-black text-emerald-400 uppercase tracking-[0.2em] mb-1">Rekomendasi Ahli</div>
                      <p className="text-[11px] text-emerald-800 italic font-bold">"{detail.recommendation}"</p>
                    </div>
                  </div>
                ))}
             </div>
          </div>
