              </div>
              <div>
                <h4 className="text-white font-black text-base uppercase tracking-widest leading-none">Mentor Auditor AI</h4>
                <div className="flex items-center gap-2 mt-2">
                  <span className="w-2.5 h-2.5 bg-emerald-500 rounded-full animate-pulse shadow-[0_0_8px_rgba(16,185,129,0.8)]"></span>
                  <span className="text-[10px] text-slate-400 font-black uppercase tracking-[0.2em]">Analisis Aktif</span>
