              ))}
              {isTyping && (
                <div className="flex justify-start mr-10">
                  <div className="bg-slate-800 p-5 rounded-[2rem] rounded-tl-none text-[10px] text-emerald-500 font-black uppercase tracking-[0.3em] animate-pulse flex items-center gap-2">
