import { GoogleGenAI, Type } from "@google/genai";
import { EvaluationReport, ChatMessage } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export async function analyzeLearningAsset(
  input: { 
    imageParts?: { inlineData: { data: string; mimeType: string } }[], 
    textContext?: string,
    videoOpeningFrames?: { inlineData: { data: string; mimeType: string } }[],
    videoClosingFrames?: { inlineData: { data: string; mimeType: string } }[]
  },
  fileName: string
): Promise<EvaluationReport> {
  const model = "gemini-3-flash-preview";

  const systemInstruction = `
    Anda adalah seorang PTP AHLI MADYA (Pengembang Teknologi Pembelajaran) Senior yang juga bertindak sebagai MENTOR bagi pengembang media pembelajaran di Kemenkes RI.

    TUGAS UTAMA:
    Melakukan audit EKSTRIM DETAIL, KRITIS, namun HUMANIS terhadap aset pembelajaran (PDF/SCORM + Video).

    PEDOMAN TERMINOLOGI:
    - Nama resmi adalah "Kemenkes CorpU" (Corporate University). Jangan pernah gunakan "CorU". Jika ditemukan "CorU" di aset, anggap itu kesalahan fatal dan berikan saran perbaikan.

    GAYA KOMUNIKASI (MENTORING):
    - Berikan feedback yang detail dan komprehensif.
    - Jelaskan *mengapa* sesuatu salah dan bagaimana dampak pedagogisnya.
    - Sapa pengguna dengan hangat namun tetap profesional.
    - Gunakan bahasa yang mengalir dan berwibawa.

    KRITERIA AUDIT KOMPREHENSIF (DEEP ANALYSIS):
    1. Kelengkapan Logo: Audit visual Logo Kemenkes CorpU, Bapelkes Cikarang, Zona Integritas (ZI), dan BerAKHLAK.
    2. Standar Visual: Font VAG Rounded untuk judul adalah wajib. Palet warna Kemenkes (Tosca, Hijau Muda, Kuning).
    3. Video Opening (Mentor Check): 
       - Sapaan "ASN Pembelajar" atau "Sahabat Pembelajar" adalah wajib.
       - Presenter harus menyebutkan: Nama, Jabatan, Instansi.
       - Harus ada: Nama Materi, Tujuan, dan Relevansi dengan pekerjaan sehari-hari.
       - Kalimat penyemangat di akhir opening.
       - Durasi: Mutlak maksimal 60 detik.
    4. Video Closing: Harus ada ucapan terima kasih, ajakan materi selanjutnya, dan LAYAR PENUTUP yang berisi: Nama Bapelkes Cikarang, Lokasi, Website, dan Media Sosial.
    5. Tim Penyusun: Cek keberadaan slide/halaman tim (PJ, WI/Ahli Materi, PTP/Pengembang Media).
    6. Panduan Penggunaan: Penjelasan cara navigasi.
    7. Hasil Belajar & 8. Indikator: Kesesuaian dengan kurikulum (jika ada data teks).
    9. Jabaran Materi & 10. Materi Pokok: Kedalaman konten dan interaktivitas.
    11. Refleksi: Slide "Sekarang Saya Tahu" untuk internalisasi materi.
    12. Progress Bar: Indikator visual kemajuan.
    13. Kualitas Bahasa & KBBI (PEDANTIK):
        - Audit typo per kata. Contoh: 'silahkan' (salah) -> 'silakan' (benar).
        - Audit spasi ganda, spasi sebelum tanda baca, dan huruf kapital.
        - Perhatikan kata-kata serapan teknis medis/pembelajaran.

    FORMAT OUTPUT:
    - Harus JSON sesuai schema.
    - Summary harus berupa paragraf bimbingan yang humanis dan menyemangati.
    - Recommendation harus sangat teknis: "Ganti teks di slide 3 baris 2 dari '...' menjadi '...'".
  `;

  const responseSchema = {
    type: Type.OBJECT,
    properties: {
      assetName: { type: Type.STRING },
      overallScore: { type: Type.NUMBER },
      logoDetected: { type: Type.BOOLEAN },
      userGuidePresent: { type: Type.BOOLEAN },
      videoAudit: {
        type: Type.OBJECT,
        properties: {
          openingValid: { type: Type.BOOLEAN },
          closingValid: { type: Type.BOOLEAN },
          durationOk: { type: Type.BOOLEAN }
        },
        required: ["openingValid", "closingValid", "durationOk"]
      },
      typosFound: { type: Type.ARRAY, items: { type: Type.STRING } },
      details: {
        type: Type.ARRAY,
        items: {
          type: Type.OBJECT,
          properties: {
            criterion: { type: Type.STRING },
            status: { type: Type.STRING },
            finding: { type: Type.STRING },
            recommendation: { type: Type.STRING }
          },
          required: ["criterion", "status", "finding", "recommendation"]
        }
      },
      summary: { type: Type.STRING }
    },
    required: ["assetName", "overallScore", "logoDetected", "userGuidePresent", "videoAudit", "typosFound", "details", "summary"]
  };

  const parts: any[] = [];
  if (input.imageParts) parts.push(...input.imageParts);
  if (input.textContext) parts.push({ text: `KONTEN TEKS UNTUK AUDIT KBBI:\n${input.textContext}` });
  if (input.videoOpeningFrames) {
    parts.push({ text: "VISUAL VIDEO OPENING (Cek Presenter & Sapaan):" });
    parts.push(...input.videoOpeningFrames);
  }
  if (input.videoClosingFrames) {
    parts.push({ text: "VISUAL VIDEO CLOSING (Cek Layar Penutup & Medsos):" });
    parts.push(...input.videoClosingFrames);
  }

  parts.push({ text: `Analisis aset: ${fileName}. Berikan review mentor yang mendalam dan manusiawi.` });

  const response = await ai.models.generateContent({
    model: model,
    contents: [{ parts }],
    config: {
      systemInstruction: systemInstruction,
      responseMimeType: "application/json",
      responseSchema: responseSchema,
      temperature: 0.15
    },
  });

  const result = JSON.parse(response.text);
  return { ...result, id: crypto.randomUUID(), timestamp: Date.now() };
}

export async function chatAboutReport(
  report: EvaluationReport,
  userMessage: string,
  history: ChatMessage[]
): Promise<string> {
  const model = "gemini-3-flash-preview";

  // Menyiapkan ringkasan temuan untuk konteks chat agar AI tahu isi dokumen
  const findingsSummary = report.details.map(d => `${d.criterion}: ${d.status} - ${d.finding}`).join('\n');
  const typoSummary = report.typosFound.length > 0 ? `Kesalahan bahasa: ${report.typosFound.join(', ')}` : "Tidak ada kesalahan bahasa.";

  const chat = ai.chats.create({
    model: model,
    config: {
      systemInstruction: `Anda adalah PTP Senior Kemenkes, rekan diskusi akademik profesional.

      KONTEKS BERKAS YANG DIUNGGAH (${report.assetName}):
      - Skor: ${report.overallScore}/100
      - Temuan Utama:
      ${findingsSummary}
      - Audit Bahasa: ${typoSummary}

      ATURAN DISKUSI:
      1. Dasar jawaban UTAMA harus berdasarkan data temuan berkas di atas.
      2. Jika pertanyaan di luar isi berkas, jawab secara normatif berdasarkan teori penyusunan aset pembelajaran.
      3. Jawab LANGSUNG ke poin tanpa prolog, sapaan pembuka, atau basa-basi bertele-tele.
      4. Gunakan bahasa akademik yang santai tapi lugas (to the point).
      5. JANGAN berikan usulan/saran/masukan jika tidak diminta secara eksplisit oleh user.
      6. DILARANG menggunakan format bold (**), italic (*), atau markdown. Gunakan teks polos saja.
      7. Jika bisa dijawab dengan sangat singkat, lakukan.`
    }
  });

  const response = await chat.sendMessage({ message: userMessage });
  return response.text || "Koneksi terputus.";
}

import React, { useState, useRef, useEffect } from 'react';
import Header from './components/Header';
import ReportView from './components/ReportView';
import GuidelineView from './components/GuidelineView';
import { AppState, EvaluationReport } from './types';
import { analyzeLearningAsset } from './services/geminiService';

// @ts-ignore
const pdfjsLib = window['pdfjs-dist/build/pdf'];
pdfjsLib.GlobalWorkerOptions.workerSrc = 'https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.worker.min.js';
// @ts-ignore
const JSZip = window.JSZip;

const App: React.FC = () => {
  const [state, setState] = useState<AppState>({
    view: 'home',
    files: { pdf: null, scorm: null, videoOpening: null, videoClosing: null },
    isAnalyzing: false,
    report: null,
    history: [],
    error: null,
    progress: 0,
    chatHistory: [],
    isChatting: false
  });

  const [activeSource, setActiveSource] = useState<'pdf' | 'scorm' | null>(null);

  useEffect(() => {
    const saved = localStorage.getItem('smartaset_history');
    if (saved) {
      try { setState(prev => ({ ...prev, history: JSON.parse(saved) })); } 
      catch (e) { console.error("History parse failed"); }
    }
  }, []);

  const saveToHistory = (report: EvaluationReport) => {
    const updatedHistory = [report, ...state.history].slice(0, 10);
    setState(prev => ({ ...prev, history: updatedHistory }));
    localStorage.setItem('smartaset_history', JSON.stringify(updatedHistory));
  };

  const extractFramesFromVideo = async (file: File): Promise<{ inlineData: { data: string, mimeType: string } }[]> => {
    return new Promise((resolve) => {
      const video = document.createElement('video');
      video.preload = 'metadata';
      video.src = URL.createObjectURL(file);
      video.muted = true;

      video.onloadedmetadata = () => {
        const frames: { inlineData: { data: string, mimeType: string } }[] = [];
        const captureTimes = [0.5, video.duration / 2, video.duration - 0.5];
        let captured = 0;

        const capture = () => {
          const canvas = document.createElement('canvas');
          canvas.width = video.videoWidth;
          canvas.height = video.videoHeight;
          const ctx = canvas.getContext('2d');
          ctx?.drawImage(video, 0, 0);
          frames.push({ inlineData: { data: canvas.toDataURL('image/jpeg', 0.8).split(',')[1], mimeType: 'image/jpeg' } });
          captured++;

          if (captured < captureTimes.length) {
            video.currentTime = captureTimes[captured];
          } else {
            resolve(frames);
          }
        };

        video.onseeked = capture;
        video.currentTime = captureTimes[0];
      };
    });
  };

  const handleFileUpload = (type: 'pdf' | 'scorm', file: File | null) => {
    if (!file) {
      setActiveSource(null);
      setState(prev => ({ ...prev, files: { ...prev.files, [type]: null }, error: null }));
      return;
    }

    setActiveSource(type);
    setState(prev => ({
      ...prev,
      files: {
        ...prev.files,
        pdf: type === 'pdf' ? file : null,
        scorm: type === 'scorm' ? file : null
      },
      error: null
    }));
  };

  const startAnalysis = async () => {
    if (!state.files.pdf && !state.files.scorm) {
      setState(prev => ({ ...prev, error: "Pilih salah satu sumber utama: PDF atau SCORM." }));
      return;
    }

    setState(prev => ({ ...prev, isAnalyzing: true, progress: 5 }));

    try {
      let imageParts = [];
      let textContext = "";
      let videoOpeningFrames = [];
      let videoClosingFrames = [];

      // Deep Extract PDF
      if (state.files.pdf) {
        const arrayBuffer = await state.files.pdf.arrayBuffer();
        const pdf = await pdfjsLib.getDocument({ data: arrayBuffer }).promise;
        const pagesToScan = Math.min(pdf.numPages, 12); // Scan more pages for better detail
        for (let i = 1; i <= pagesToScan; i++) {
          const page = await pdf.getPage(i);
          const viewport = page.getViewport({ scale: 2.0 });
          const canvas = document.createElement('canvas');
          canvas.height = viewport.height;
          canvas.width = viewport.width;
          await page.render({ canvasContext: canvas.getContext('2d')!, viewport }).promise;
          imageParts.push({ inlineData: { data: canvas.toDataURL('image/jpeg', 0.8).split(',')[1], mimeType: 'image/jpeg' } });

          const text = await page.getTextContent();
          textContext += `[Halaman ${i}]\n${text.items.map((item: any) => item.str).join(' ')}\n\n`;
          setState(prev => ({ ...prev, progress: 5 + Math.round((i / pagesToScan) * 45) }));
        }
      }

      // Deep Extract SCORM
      if (state.files.scorm) {
        const zip = await JSZip.loadAsync(state.files.scorm);
        textContext = "STRUKTUR PAKET SCORM:\n";
        const manifest = await zip.file("imsmanifest.xml")?.async("string");
        if (manifest) textContext += `MANIFEST XML:\n${manifest}\n`;

        const htmlFiles = Object.keys(zip.files).filter(f => f.endsWith('.html') || f.endsWith('.htm')).slice(0, 8);
        for (const f of htmlFiles) {
          const content = await zip.file(f)?.async("string");
          if (content) textContext += `\nISI KONTEN FILE (${f}):\n${content.replace(/<[^>]*>?/gm, ' ').substring(0, 2500)}`;
        }
        setState(prev => ({ ...prev, progress: 50 }));
      }

      if (state.files.videoOpening) {
        videoOpeningFrames = await extractFramesFromVideo(state.files.videoOpening);
      }
      if (state.files.videoClosing) {
        videoClosingFrames = await extractFramesFromVideo(state.files.videoClosing);
      }

      setState(prev => ({ ...prev, progress: 75 }));

      const fileName = state.files.pdf?.name || state.files.scorm?.name || "Aset Pembelajaran";
      const result = await analyzeLearningAsset({ 
        imageParts, 
        textContext, 
        videoOpeningFrames, 
        videoClosingFrames 
      }, fileName);

      saveToHistory(result);
      setState(prev => ({ ...prev, isAnalyzing: false, report: result, view: 'report', progress: 100 }));
    } catch (err) {
      console.error(err);
      setState(prev => ({ ...prev, isAnalyzing: false, error: "Gagal memproses audit. Silakan periksa format file Anda." }));
    }
  };

  return (
    <div className="min-h-screen flex flex-col bg-slate-50">
      <Header onNavigate={(v) => setState(prev => ({ ...prev, view: v }))} activeView={state.view} />

      <main className="flex-grow max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-10 w-full">
        {state.isAnalyzing ? (
          <div className="max-w-xl mx-auto py-20 text-center space-y-8 animate-pulse">
            <div className="relative w-24 h-24 mx-auto">
               <div className="absolute inset-0 border-4 border-emerald-100 rounded-full"></div>
               <div className="absolute inset-0 border-4 border-emerald-600 rounded-full border-t-transparent animate-spin"></div>
            </div>
            <div className="space-y-4">
              <h3 className="text-2xl font-black text-slate-800 tracking-tight">Analisis Aset Sedang Berjalan...</h3>
              <div className="w-full bg-slate-200 h-2.5 rounded-full overflow-hidden shadow-inner">
                <div className="bg-emerald-600 h-full transition-all duration-500 shadow-[0_0_15px_rgba(16,185,129,0.5)]" style={{ width: `${state.progress}%` }}></div>
              </div>
              <p className="text-sm text-slate-500 font-medium">Mentor AI sedang meninjau kriteria pedoman aset Anda secara mendalam...</p>
            </div>
          </div>
        ) : state.view === 'report' && state.report ? (
          <ReportView report={state.report} onReset={() => {
            setState(prev => ({ ...prev, view: 'home', report: null, files: { pdf: null, scorm: null, videoOpening: null, videoClosing: null } }));
            setActiveSource(null);
          }} />
        ) : state.view === 'guideline' ? (
          <GuidelineView onNavigate={(v) => setState(prev => ({ ...prev, view: v }))} />
        ) : state.view === 'history' ? (
          <div className="max-w-4xl mx-auto py-10">
            <h2 className="text-3xl font-black text-slate-900 mb-8 tracking-tight flex items-center gap-3">
              <svg className="w-8 h-8 text-emerald-600" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M12 8v4l3 3m6-3a9 9 0 11-18 0 9 9 0 0118 0z" /></svg>
              Riwayat Penilaian PTP
            </h2>
            <div className="grid gap-5">
              {state.history.length > 0 ? state.history.map(item => (
                <div key={item.id} onClick={() => setState(prev => ({ ...prev, report: item, view: 'report' }))} className="bg-white p-6 rounded-[2rem] border border-slate-200 hover:border-emerald-500 cursor-pointer flex justify-between items-center group shadow-sm transition-all hover:shadow-xl">
                  <div className="flex gap-6 items-center">
                    <div className="w-16 h-16 bg-emerald-50 text-emerald-600 rounded-2xl flex items-center justify-center font-black text-2xl group-hover:bg-emerald-600 group-hover:text-white transition-all shadow-inner">{item.overallScore}</div>
                    <div>
                      <h4 className="font-bold text-slate-900 text-lg group-hover:text-emerald-700 transition-colors">{item.assetName}</h4>
                      <p className="text-xs text-slate-400 font-bold uppercase tracking-widest mt-1">{new Date(item.timestamp).toLocaleDateString('id-ID', { day: 'numeric', month: 'long', year: 'numeric' })}</p>
                    </div>
                  </div>
                  <div className="bg-slate-50 px-4 py-2 rounded-xl text-[10px] font-black text-slate-400 group-hover:bg-emerald-100 group-hover:text-emerald-700 transition-all uppercase tracking-widest">Detail Laporan</div>
                </div>
              )) : (
                <div className="text-center py-20 bg-white rounded-[3rem] border-2 border-dashed border-slate-200">
                  <p className="text-slate-400 font-medium">Belum ada riwayat penilaian aset.</p>
                </div>
              )}
            </div>
          </div>
        ) : (
          <div className="max-w-5xl mx-auto space-y-12">
            <div className="text-center space-y-5">
              <div className="inline-block px-4 py-1 bg-emerald-100 text-emerald-700 rounded-full text-[10px] font-black uppercase tracking-[0.3em]">SmartAset v 1.0 Professional</div>
